/* TBK V74 - module externalise : tbk-v74-03-core.js */
function forceHideToolbarButtons(){document.querySelectorAll('[data-toolbar]').forEach(el=>{el.hidden=true;el.style.display='none'});}



const STORAGE='tbk_tournois_dm_dh_v1';
const POOLS=['A','B','C','D','E','F','G','H']; const DH_POOLS=['A','B','C','D'];
const poolPairs=[[1,2],[3,4],[1,3],[2,4],[1,4],[2,3]];
const defaultState=()=>({settings:{start:'20:00',rotation:20,courts:9,participantFee:0,minRestBetweenMatches:0},dm:{name:'Double Mixte',prefix:'DM',teamCount:32,pools:POOLS,teams:{},matches:[],ko:[]},dh:{name:'Double Homme',prefix:'DH',teamCount:16,pools:DH_POOLS,teams:{},matches:[],ko:[]},checkin:{dm:{},dh:{}}});
let state=load()||init(defaultState());  
let plannedSequence=[];  
let selectedPlanningMatch=null;
let highlightedTeam=null;
let highlightedAvailableOnly=false;
let planningFilter='all';
let emargementSearch='';
let planningSearch='';
function init(s){initTeams(s.dm,false);initTeams(s.dh,true);s.dm.matches=makePoolMatches('dm',1,s);s.dh.matches=makePoolMatches('dh',100,s);s.dm.ko=makeDMKO();s.dh.ko=makeDHKO();for(let k of ['dm','dh']) for(let id in s[k].teams) s.checkin[k][id]={present1:false,present2:false,absent1:true,absent2:true,paid1:false,paid2:false};return s}
function initTeams(comp,isDH){let idx=1;comp.pools.forEach(p=>{for(let pos=1;pos<=4;pos++){comp.teams[idx]={id:idx,pool:p,pos:pos,j1:'',j2:'',club:''};idx++}})}
function makePoolMatches(key,start,s=state){let comp=(key==='dm')?s.dm:s.dh, arr=[], n=start;comp.pools.forEach(p=>{let ids=Object.values(comp.teams).filter(t=>t.pool===p).sort((a,b)=>a.pos-b.pos).map(t=>t.id);poolPairs.forEach(pair=>{arr.push({id:n++,comp:key,phase:'Poules',pool:p,a:ids[pair[0]-1],b:ids[pair[1]-1],scores:[[null,null],[null,null],[null,null]],court:null,rotation:null,time:null,done:false})})});return arr}
function koMatch(id,comp,phase,bracket,a,b){return{id,comp,phase,bracket,a,b,scores:[[null,null],[null,null],[null,null]],court:null,rotation:null,time:null,done:false,winner:null,loser:null}}
function makeDMKO(){let m=[];let main=[['1A','2B'],['1C','2D'],['1E','2F'],['1G','2H'],['2A','1B'],['2C','1D'],['2E','1F'],['2G','1H']];let cons=[['3A','4B'],['3C','4D'],['3E','4F'],['3G','4H'],['4A','3B'],['4C','3D'],['4E','3F'],['4G','3H']];main.forEach((p,i)=>m.push(koMatch(49+i,'dm','1/8 Finale','Principale',p[0],p[1])));cons.forEach((p,i)=>m.push(koMatch(65+i,'dm','1/8 Finale C','Consolante',p[0],p[1])));for(let i=0;i<4;i++)m.push(koMatch(57+i,'dm','1/4 Finale','Principale','G'+(49+i*2),'G'+(50+i*2)));for(let i=0;i<4;i++)m.push(koMatch(73+i,'dm','1/4 Finale C','Consolante','G'+(65+i*2),'G'+(66+i*2)));m.push(koMatch(61,'dm','1/2 Finale','Principale','G57','G58'));m.push(koMatch(62,'dm','1/2 Finale','Principale','G59','G60'));m.push(koMatch(77,'dm','1/2 Finale C','Consolante','G73','G74'));m.push(koMatch(78,'dm','1/2 Finale C','Consolante','G75','G76'));m.push(koMatch(63,'dm','3eme/4eme','Principale','P61','P62'));m.push(koMatch(64,'dm','Finale P','Principale','G61','G62'));m.push(koMatch(79,'dm','3eme/4eme C','Consolante','P77','P78'));m.push(koMatch(80,'dm','Finale C','Consolante','G77','G78'));return m}
function makeDHKO(){let m=[];let main=[['1A','2B'],['1C','2D'],['2A','1B'],['2C','1D']];let cons=[['3A','4B'],['3C','4D'],['4A','3B'],['4C','3D']];main.forEach((p,i)=>m.push(koMatch(124+i,'dh','1/4 Finale','Principale',p[0],p[1])));cons.forEach((p,i)=>m.push(koMatch(132+i,'dh','1/4 Finale C','Consolante',p[0],p[1])));m.push(koMatch(128,'dh','1/2 Finale','Principale','G124','G125'));m.push(koMatch(129,'dh','1/2 Finale','Principale','G126','G127'));m.push(koMatch(136,'dh','1/2 Finale C','Consolante','G132','G133'));m.push(koMatch(137,'dh','1/2 Finale C','Consolante','G134','G135'));m.push(koMatch(130,'dh','3eme/4eme','Principale','P128','P129'));m.push(koMatch(131,'dh','Finale','Principale','G128','G129'));m.push(koMatch(138,'dh','3eme/4eme C','Consolante','P136','P137'));m.push(koMatch(139,'dh','Finale C','Consolante','G136','G137'));return m}
function load(){try{return JSON.parse(localStorage.getItem(STORAGE))}catch(e){return null}}
function save(){localStorage.setItem(STORAGE,JSON.stringify(state));toast('Données sauvegardées dans le navigateur.')} function toast(t){alert(t)}
function teamCode(key,id){return `${key.toUpperCase()}-${String(id).padStart(2,'0')}`}
function teamLabel(key,id){if(!id) return ''; if(typeof id==='string') return resolveSeed(key,id,true); let t=state[key].teams[id]; if(!t) return teamCode(key,id); let names=[t.j1,t.j2].filter(Boolean).join(' / '); return names?`${teamCode(key,id)} - ${names}`:teamCode(key,id)}
function resolveSeed(key,seed,label=false){if(!seed) return ''; if(typeof seed==='number') return label?teamLabel(key,seed):seed; let rank=seed.match(/^([1-4])([A-H])$/); if(rank){let r=+rank[1],p=rank[2], standings=getStandings(key,p);let t=standings[r-1];return label?(t?teamLabel(key,t.id):seed):(t?t.id:null)} let ref=seed.match(/^([GP])(\d+)$/); if(ref){let m=getAllMatches(key).find(x=>x.id==+ref[2]); if(!m) return label?seed:null; computeMatchWinner(m); let id=ref[1]==='G'?m.winner:m.loser; return label?(id?teamLabel(key,id):seed):id} return seed}
function getAllMatches(key){return [...state[key].matches,...state[key].ko]}
function scoreValueAt(m,setIdx,side){let v=m&&m.scores&&m.scores[setIdx]?m.scores[setIdx][side]:null;return Number.isFinite(v)?v:null}
function setScore(m,setIdx,side,val){
  if(!m){alert('Match introuvable pour la saisie du score.');return false}
  if(isKOLockedByPools(m)){alert(poolLockReason(m));renderAll(false);return false}
  if(matchHasAbsent(m)){alert('Score impossible : au moins un participant de ce match est marqué absent dans l émargement.');renderAll(false);return false}
  let newVal=val===''?null:+val;
  if(val!==''&&!Number.isFinite(newVal))newVal=null;
  let oldVal=scoreValueAt(m,setIdx,side);
  if(oldVal===newVal)return true;
  let wasDone=!!m.done;
  if(wasDone){
    let ok=confirm(`Ce match est déjà terminé (${m.comp.toUpperCase()} ${m.id}).\n\nConfirmer la modification des scores ?`);
    if(!ok){renderAll(false);return false}
  }
  m.scores[setIdx][side]=newVal;
  m.done=isMatchComplete(m);
  computeMatchWinner(m);
  if(m.done&&!wasDone){
    if(!m.startedAt&&Number.isFinite(m.court))m.startedAt=Date.now();
    if(m.startedAt&&!m.endedAt)m.endedAt=Date.now();
  }
  if(!m.done){delete m.endedAt}
  renderAll(false);
  return true
}
function isMatchComplete(m){let played=m.scores.filter(s=>Number.isFinite(s[0])&&Number.isFinite(s[1])&&s[0]!==s[1]); if(played.length<2)return false; let wa=played.filter(s=>s[0]>s[1]).length, wb=played.filter(s=>s[1]>s[0]).length;return wa===2||wb===2}
function computeMatchWinner(m){let played=m.scores.filter(s=>Number.isFinite(s[0])&&Number.isFinite(s[1])&&s[0]!==s[1]);let wa=played.filter(s=>s[0]>s[1]).length, wb=played.filter(s=>s[1]>s[0]).length;let a=resolveSeed(m.comp,m.a),b=resolveSeed(m.comp,m.b);m.winner=null;m.loser=null;if(wa>=2){m.winner=a;m.loser=b}else if(wb>=2){m.winner=b;m.loser=a}return m.winner}
function teamWinnerClass(m,side){computeMatchWinner(m);let id=side===0?resolveSeed(m.comp,m.a):resolveSeed(m.comp,m.b);return m.done&&id&&m.winner===id?'winner-team':''}  
function canEditScores(m){return !matchHasAbsent(m)&&!isKOLockedByPools(m)}  
function teamHasAbsent(key,id){if(!id)return false;let c=ensureCheckRecord(key,id);return !!(c.absent1||c.absent2)}
function matchHasAbsent(m){if(!m)return false;let r=matchTeamsResolved(m);return teamHasAbsent(m.comp,r.a)||teamHasAbsent(m.comp,r.b)}
function releaseCourtsForTeam(key,id){getAllMatches(key).forEach(m=>{let r=matchTeamsResolved(m);if(!m.done&&r.teams.includes(id)){delete m.manualCourt;m.court=null;delete m.startedAt;delete m.endedAt}})}  
function absentTeamTitle(m){let r=matchTeamsResolved(m),names=[];if(teamHasAbsent(m.comp,r.a))names.push(teamLabel(m.comp,r.a));if(teamHasAbsent(m.comp,r.b))names.push(teamLabel(m.comp,r.b));return names.length?`Equipe indisponible / participant absent : ${names.join(' / ')}`:'Participant absent'}
function arePoolMatchesComplete(key){return state[key].matches.length>0&&state[key].matches.every(m=>m.done)}
function isKOMatch(m){return m&&m.phase!=='Poules'}
function isKOLockedByPools(m){return isKOMatch(m)&&!arePoolMatchesComplete(m.comp)}
function poolLockReason(m){return `Match de tableau verrouillé : tous les matchs de poules ${m.comp.toUpperCase()} doivent être terminés avant de continuer le tournoi.`}

function scoreInputs(m){let locked=isKOLockedByPools(m),disabled=!canEditScores(m),dis=disabled?'disabled':'',reason=locked?poolLockReason(m):(disabled?absentTeamTitle(m):''),title=disabled?` title="${reason}"`:'';return `<div class="score-line"${title}>${m.scores.map((s,i)=>`<div class="score-set"><input class="score" type="number" inputmode="numeric" min="0" max="30" step="1" value="${s[0]??''}" ${dis} onfocus="this.select()" onchange="setScoreById('${m.comp}',${m.id},${i},0,this.value)">-<input class="score" type="number" inputmode="numeric" min="0" max="30" step="1" value="${s[1]??''}" ${dis} onfocus="this.select()" onchange="setScoreById('${m.comp}',${m.id},${i},1,this.value)"></div>`).join('')}</div>`}
function setScoreById(key,id,setIdx,side,val){let m=getAllMatches(key).find(x=>x.id===id);return setScore(m,setIdx,side,val)}
function matchStatsFor(m,teamId){computeMatchWinner(m);let other=(resolveSeed(m.comp,m.a)===teamId)?resolveSeed(m.comp,m.b):resolveSeed(m.comp,m.a);let played=m.scores.filter(s=>Number.isFinite(s[0])&&Number.isFinite(s[1])&&s[0]!==s[1]);let forSets=0,againstSets=0,forPts=0,againstPts=0;if(!m.done)return null;let isA=resolveSeed(m.comp,m.a)===teamId;played.forEach(s=>{let x=isA?s[0]:s[1],y=isA?s[1]:s[0];forPts+=x;againstPts+=y;if(x>y)forSets++;else againstSets++});let win=m.winner===teamId;return{points:win?3:1,setDiff:forSets-againstSets,ptDiff:forPts-againstPts,forPts,againstPts,win,other}}
function getStandings(key,pool){let teams=Object.values(state[key].teams).filter(t=>t.pool===pool).sort((a,b)=>a.pos-b.pos);let rows=teams.map(t=>({id:t.id,pool:pool,pos:t.pos,points:0,setDiff:0,ptDiff:0,wins:0,played:0}));state[key].matches.filter(m=>m.pool===pool).forEach(m=>{[resolveSeed(key,m.a),resolveSeed(key,m.b)].forEach(id=>{let st=matchStatsFor(m,id); if(st){let r=rows.find(x=>x.id===id);r.points+=st.points;r.setDiff+=st.setDiff;r.ptDiff+=st.ptDiff;r.wins+=st.win?1:0;r.played++}})});return rows.sort((a,b)=>b.points-a.points||b.setDiff-a.setDiff||b.ptDiff-a.ptDiff||a.pos-b.pos).map((r,i)=>({...r,rank:i+1}))}
function renderComp(key){let comp=state[key];let frozen=isPoolsFrozen(key);let html=`${tournamentSubMenu(key)}<div class="card tournament-sticky-header"><div class="row"><div class="kpi"><span>Compétition</span><br><strong>${comp.prefix}</strong><div>${comp.name}</div></div><div class="kpi"><span>Equipes</span><br><strong>${comp.teamCount}</strong><div>${comp.pools.length} poules de 4</div></div><div class="kpi"><span>Matchs poules</span><br><strong>${comp.matches.length}</strong><div>+ tableau principal/consolante</div></div></div></div><div class="card wide"><div class="row" style="justify-content:space-between;align-items:flex-start"><h2 style="margin:0">Liste des équipes</h2><div>${frozen?`<button class="warn" onclick="togglePoolsFrozen('${key}',false)">🔓 Défiger les poules</button>`:`<button onclick="togglePoolsFrozen('${key}',true)">🔒 Figer les poules</button>`}</div></div><div class="${frozen?'locked-info':'notice'}" style="margin:10px 0">${frozen?'Poules figées : la saisie et les modifications de la liste des équipes sont verrouillées.':'Les poules ne sont pas figées : les équipes, poules, rangs et clubs restent modifiables.'}</div><div class="teams-and-summary"><div class="teams-list-zone">${teamsTable(key)}</div>${poolOverview(key)}</div></div><div class="layout pool-layout ${key}-pool-layout">`;comp.pools.forEach(p=>{html+=`<div class="card pool-card"><div class="poolTitle">Poule ${p}</div>${poolTable(key,p)}${poolMatchesTable(key,p)}</div>`});html+=`</div><div class="card wide"><h2>Tableaux finaux - ${comp.name}</h2>${koTable(key)}</div>`;document.getElementById(key).innerHTML=html}  
function teamsTable(key){let comp=state[key];let frozen=isPoolsFrozen(key),dis=frozen?'disabled':'',inputCls=frozen?' locked-input':'';let headers=key==='dh'?['Poule','Rang','N°','DH Joueur 1','Club J1','DH Joueur 2','Club J2','Nouvelle poule','Nouveau rang','Action']:['Poule','Rang','N°','Joueur 1','Club J1','Joueur 2','Club J2','Nouvelle poule','Nouveau rang','Action'];let body=Object.values(comp.teams).sort((a,b)=>a.pool.localeCompare(b.pool)||a.pos-b.pos).map(t=>{ensureParticipantClubs(t);return `<tr class="${teamHasAbsent(key,t.id)?'absent-team':''}"><td class="sub">${t.pool}</td><td>${t.pos}</td><td>${teamCode(key,t.id)}</td><td class="inputcell"><input class="player${inputCls}" value="${esc(t.j1)}" ${dis} onchange="teamEdit('${key}',${t.id},'j1',this.value)"></td><td class="inputcell"><input class="club player-club${inputCls}" value="${participantClub(t,1)}" ${dis} onchange="teamEdit('${key}',${t.id},'club1',this.value)"></td><td class="inputcell"><input class="player${inputCls}" value="${esc(t.j2)}" ${dis} onchange="teamEdit('${key}',${t.id},'j2',this.value)"></td><td class="inputcell"><input class="club player-club${inputCls}" value="${participantClub(t,2)}" ${dis} onchange="teamEdit('${key}',${t.id},'club2',this.value)"></td><td>${poolMoveSelect(key,t)}</td><td>${posMoveSelect(key,t)}</td><td><button class="secondary move-btn" ${dis} onclick="moveTeamSlot('${key}',${t.id})">Déplacer</button></td></tr>`}).join('');return `<div class="small" style="margin-bottom:6px">Pour changer une équipe de poule ou de rang : choisis la nouvelle position puis clique sur <b>Déplacer</b>. Les colonnes <b>Club J1</b> et <b>Club J2</b> correspondent au club de rattachement de chaque joueur. Si la place est déjà prise, l'application propose une permutation. ${frozen?'<b>Les poules étant figées, ces actions sont désactivées.</b>':''}</div><table class="excel teams-list-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table>`}    
function teamEdit(key,id,field,value){if(isPoolsFrozen(key)){alert('Les poules sont figées : modification impossible.');renderAll(false);return}let t=state[key].teams[id];if(!t)return;ensureParticipantClubs(t);t[field]=value;if(field==='club1'||field==='club2')syncLegacyClub(t);renderAll(false)}  
function isPoolsFrozen(key){return !!state[key].poolsFrozen}
function togglePoolsFrozen(key,freeze){if(freeze){if(!confirm('Figer les poules de cette compétition ?\n\nLa saisie et les modifications de la liste des équipes seront verrouillées.'))return;state[key].poolsFrozen=true}else{if(!confirm('Défiger les poules de cette compétition ?\n\nLa liste des équipes redeviendra modifiable.'))return;state[key].poolsFrozen=false}renderAll(false)}
function poolMoveSelect(key,t){let pools=state[key].pools,dis=isPoolsFrozen(key)?'disabled':'';return `<select class="move-select" id="movePool_${key}_${t.id}" ${dis}>${pools.map(p=>`<option value="${p}" ${p===t.pool?'selected':''}>${p}</option>`).join('')}</select>`}
function posMoveSelect(key,t){let dis=isPoolsFrozen(key)?'disabled':'';return `<select class="move-select" id="movePos_${key}_${t.id}" ${dis}>${[1,2,3,4].map(p=>`<option value="${p}" ${p===t.pos?'selected':''}>${p}</option>`).join('')}</select>`}
function moveTeamSlot(key,id){if(isPoolsFrozen(key)){alert('Les poules sont figées : déplacement impossible.');return}let comp=state[key],team=comp.teams[id];if(!team)return;let poolEl=document.getElementById(`movePool_${key}_${id}`),posEl=document.getElementById(`movePos_${key}_${id}`);let newPool=poolEl?poolEl.value:team.pool,newPos=posEl?+posEl.value:team.pos;if(team.pool===newPool&&team.pos===newPos){alert('Cette équipe est déjà à cette position.');return}let occupied=Object.values(comp.teams).find(t=>t.id!==id&&t.pool===newPool&&t.pos===newPos);let msg=`Déplacer ${teamLabel(key,id)} de ${team.pool}${team.pos} vers ${newPool}${newPos} ?

Attention : les matchs et scores de cette compétition seront réinitialisés pour garantir un planning cohérent.`;if(occupied){msg=`La place ${newPool}${newPos} est déjà prise par ${teamLabel(key,occupied.id)}.

Alternative proposée : permuter les deux équipes.
- ${teamLabel(key,id)} ira en ${newPool}${newPos}
- ${teamLabel(key,occupied.id)} ira en ${team.pool}${team.pos}

Attention : les matchs et scores de cette compétition seront réinitialisés.

Cliquer sur OK pour permuter, ou Annuler pour choisir une autre place.`}if(!confirm(msg))return;if(occupied){let oldPool=team.pool,oldPos=team.pos;team.pool=newPool;team.pos=newPos;occupied.pool=oldPool;occupied.pos=oldPos}else{team.pool=newPool;team.pos=newPos}rebuildCompetitionAfterTeamMove(key);selectedPlanningMatch=null;renderAll(false)}
function rebuildCompetitionAfterTeamMove(key){let comp=state[key];if(key==='dm'){comp.matches=makePoolMatches('dm',1,state);comp.ko=makeDMKO()}else{comp.matches=makePoolMatches('dh',100,state);comp.ko=makeDHKO()} }

function matchTimeLabel(m){if(m&&m.startedAt){let d=new Date(m.startedAt);return `<b>${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}</b>`}return m&&m.time?m.time:''}
function planningMatchSearchText(m){let r=matchTeamsResolved(m);return normSearch([m.id,m.comp,m.comp.toUpperCase(),teamLabel(m.comp,r.a),teamLabel(m.comp,r.b),teamCode(m.comp,r.a),teamCode(m.comp,r.b),m.phase,m.rotation,m.time].join(' '))}
function matchesPlanningSearch(m){let term=normSearch(planningSearch);return !term||planningMatchSearchText(m).includes(term)}

function poolOverview(key){let comp=state[key];let blocks=comp.pools.map(p=>{let rows=getStandings(key,p).map(r=>{let cls=(r.rank<=2?'qualified-row ':'')+(teamHasAbsent(key,r.id)?'absent-team':'');let label=teamLabel(key,r.id);return `<tr class="${cls}"><td class="rank-pill-cell"><span class="rank-pill">${r.rank}</span></td><td class="pool-overview-team" title="${esc(label)}">${label}</td><td>${r.played}</td><td><b>${r.points}</b></td><td>${r.setDiff}</td><td>${r.ptDiff}</td></tr>`}).join('');return `<div class="pool-overview-card"><div class="pool-overview-title">Poule ${p}</div><table class="excel pool-overview-table"><tr><th>#</th><th>Equipe</th><th>J</th><th>Pts</th><th>7G-7P</th><th>Diff</th></tr>${rows}</table></div>`}).join('');return `<aside class="pool-overview-panel"><div class="pool-overview-header"><h3>Vision synthétique des poules</h3><div class="small">Classement dynamique recalculé après chaque score. Les 2 premières places sont mises en évidence.</div></div><div class="pool-overview-grid">${blocks}</div></aside>`}

function poolTable(key,p){let rows=getStandings(key,p).map(r=>{let calc=(r.points*1000)+(r.setDiff*100)+r.ptDiff;let tip=`Le classement est effectué en suivant la formule suivante :  Points * 1000 + (7G-7P) * 100 + Diff ici : ${calc}`;return `<tr class="${teamHasAbsent(key,r.id)?'absent-team':''}"><td class="ranking-tooltip-cell" title="${tip}">${r.rank}${p}</td><td>${teamLabel(key,r.id)}</td><td>${r.played}</td><td>${r.wins}</td><td>${r.setDiff}</td><td>${r.ptDiff}</td><td><b>${r.points}</b></td></tr>`}).join('');return `<table class="excel pool-ranking-table" style="width:100%"><tr><th>Classement</th><th>Equipe</th><th>J</th><th>G</th><th>7G-7P</th><th>Diff pts</th><th>Points</th></tr>${rows}</table>`}  
function poolMatchesTable(key,p){let rows=state[key].matches.filter(m=>m.pool===p).map(m=>`<tr class="${m.done?'match-done':'match-pending'} ${matchHasAbsent(m)?'absent-team':''}"><td>${m.id}</td><td class="${teamWinnerClass(m,0)}">${teamLabel(key,m.a)}</td><td class="${teamWinnerClass(m,1)}">${teamLabel(key,m.b)}</td><td>${scoreInputs(m)}</td><td>${m.court??''}</td><td>${matchTimeLabel(m)}</td><td>${m.rotation??''}</td></tr>`).join('');return `<div class="pool-match-table-wrap"><table class="excel pool-match-table" style="width:100%;margin-top:6px"><colgroup><col class="col-num"><col class="col-team1"><col class="col-team2"><col class="col-scores"><col class="col-court"><col class="col-time"><col class="col-rot"></colgroup><tr><th class="compact-col">N°</th><th class="team-col">Equipe 1</th><th class="team-col">Equipe 2</th><th class="scores-col">Scores</th><th class="compact-col">Terrain</th><th class="compact-col">Heure</th><th class="compact-col">Rotation</th></tr>${rows}</table></div>`}  
function koBracketTable(key,bracket,label){let rows=state[key].ko.filter(m=>m.bracket===bracket).map(m=>`<tr class="${m.done?'match-done':''} ${matchHasAbsent(m)?'absent-team':''} ${isKOLockedByPools(m)?'ko-locked':''}"><td>${m.id}</td><td>${m.phase}</td><td class="${teamWinnerClass(m,0)}">${teamLabel(key,m.a)}</td><td class="${teamWinnerClass(m,1)}">${teamLabel(key,m.b)}</td><td>${scoreInputs(m)}</td><td>${m.court??''}</td><td>${matchTimeLabel(m)}</td></tr>`).join('');return `<div class="final-bracket"><h3>${label}</h3><table class="excel final-table"><colgroup><col class="final-num"><col class="final-phase"><col class="final-team"><col class="final-team"><col class="final-score"><col class="final-court"><col class="final-time"></colgroup><tr><th>N°</th><th>Phase</th><th>Equipe 1</th><th>Equipe 2</th><th>Scores</th><th>Terrain</th><th>Heure</th></tr>${rows}</table></div>`}  
function koTable(key){updateSchedule();return `<div class="finals-layout">${koBracketTable(key,'Principale','Tableau principal')}${koBracketTable(key,'Consolante','Tableau consolante')}</div>`}    
function selectedPlanningMatchObj(){if(!selectedPlanningMatch)return null;return getAllMatches(selectedPlanningMatch.comp).find(x=>x.id===selectedPlanningMatch.id)||null}
function matchKey(m){return m.comp+':'+m.id}
function matchTeamsResolved(m){let a=resolveSeed(m.comp,m.a),b=resolveSeed(m.comp,m.b);return{a,b,teams:[a,b].filter(Boolean)}}
function lastInProgressIndex(){let seq=globalSequence(),idx=-1;seq.forEach((m,i)=>{if(!m.done&&Number.isFinite(m.court))idx=i});return idx}
function courtWindowSize(){let v=parseInt(state.settings.courtWindow??18,10);return Math.max(1,Math.min(100,Number.isFinite(v)?v:18))}
function courtChoiceWindow(){let seq=globalSequence(),start=lastInProgressIndex()+1,items=[],limit=courtWindowSize();for(let i=start;i<seq.length&&items.length<limit;i++){if(!seq[i].done)items.push(seq[i])}return items}
function isInCourtChoiceWindow(m){return courtChoiceWindow().some(x=>matchKey(x)===matchKey(m))}
function courtChoiceWindowInfo(){let w=courtChoiceWindow();return w.length?`${w[0].rotation||''} / match ${w[0].id} à ${w[w.length-1].rotation||''} / match ${w[w.length-1].id}`:'Aucun match éligible'}
function busyTeamIdsForMatch(m){if(!m||m.done||Number.isFinite(m.court))return[];let r=matchTeamsResolved(m);return r.teams.filter(id=>globalSequence().some(x=>x.comp===m.comp&&x.id!==m.id&&!x.done&&Number.isFinite(x.court)&&matchTeamsResolved(x).teams.includes(id)))}
function busyTeamsReason(m){let ids=busyTeamIdsForMatch(m);return ids.length?`Equipe déjà engagée sur un match en cours : ${ids.map(id=>teamCode(m.comp,id)).join(' / ')}`:''}
function busyTeamsBadge(m){let ids=busyTeamIdsForMatch(m);return ids.length?`Attente ${ids.map(id=>teamCode(m.comp,id)).join(' / ')}`:''}
function matchReadiness(m){if(!m)return{ok:false,reason:'Match introuvable'};if(m.done)return{ok:false,reason:'Match terminé'};let r=matchTeamsResolved(m);if(!r.a||!r.b)return{ok:false,reason:'Participants à définir'};if(isKOLockedByPools(m))return{ok:false,reason:poolLockReason(m)};if(matchHasAbsent(m))return{ok:false,reason:absentTeamTitle(m)};let busy=busyTeamsReason(m);if(busy)return{ok:false,reason:busy};return{ok:true,reason:''}}    
function minRestBetweenMatches(){let v=parseInt(state.settings.minRestBetweenMatches??0,10);return Number.isFinite(v)&&v>0?v:0}
function restBetweenMatchesWarnings(m){let min=minRestBetweenMatches();if(!min||!m)return[];let r=matchTeamsResolved(m),now=Date.now();return r.teams.map(id=>{let last=lastFinishedAtForTeam(m.comp,id);if(!last)return null;let wait=Math.max(0,Math.round((now-last)/60000));return wait<min?{id,wait,min}:null}).filter(Boolean)}
function showRestBetweenMatchesWarning(m){let warnings=restBetweenMatchesWarnings(m);if(!warnings.length)return;let lines=warnings.map(w=>`temps entre 2 matchs : ${w.wait} min / valeur : ${w.min} min / équipe concernée : ${teamLabel(m.comp,w.id)}`);alert(lines.join('\n'))}
function selectPlanningMatch(key,id){let m=getAllMatches(key).find(x=>x.id===id);let ready=matchReadiness(m);if(!ready.ok){selectedPlanningMatch=null;alert(ready.reason);renderAll(false);return}selectedPlanningMatch={comp:key,id:id};renderAll(false)}  
function selectedRotation(){let sel=selectedPlanningMatchObj();if(sel&&!sel.done)return sel.rotation;let w=courtChoiceWindow();return w.length?w[0].rotation:null}
function availableCourts(){let n=state.settings.courts||9,sel=selectedPlanningMatchObj(),busy=new Set();globalSequence().filter(m=>!m.done).forEach(m=>{if(sel&&matchKey(sel)===matchKey(m))return;if(Number.isFinite(m.court))busy.add(m.court)});let arr=[];for(let i=1;i<=n;i++)arr.push({court:i,available:!busy.has(i)});return{courts:arr}}  
function resetWaitForMatchTeams(m){let r=matchTeamsResolved(m),now=Date.now();r.teams.forEach(id=>{let t=state[m.comp].teams[id];if(t)t.waitResetAt=now})}
function assignCourtFromPanel(court){let m=selectedPlanningMatchObj();if(!m){alert('Sélectionne d’abord un match dans le planning.');return}let ready=matchReadiness(m);if(!ready.ok){selectedPlanningMatch=null;alert(ready.reason);renderAll(false);return}let availability=availableCourts().courts.find(c=>c.court===court);if(!availability||!availability.available){alert('Ce terrain est déjà affecté à un match non terminé.');return}m.manualCourt=court;m.court=court;if(!m.startedAt)m.startedAt=Date.now();resetWaitForMatchTeams(m);renderAll(false)}  
function clearCourtSelection(key,id){let m=getAllMatches(key).find(x=>x.id===id);if(!m||m.done)return;delete m.manualCourt;m.court=null;delete m.startedAt;delete m.endedAt;renderAll(false)}  
function courtSlot(m){if(m.done)return `<span class="court-locked" title="Match terminé - terrain conservé et libéré">${m.court?'T'+m.court+' - Terminé':'Terminé'}</span>`;if(isKOLockedByPools(m))return `<span class="pool-lock-badge" title="${poolLockReason(m)}">En Attente</span>`;if(matchHasAbsent(m))return `<span class="absent-badge" title="${absentTeamTitle(m)}">Absent</span>`;let busy=busyTeamsBadge(m);if(busy)return `<span class="team-busy-badge" title="${busyTeamsReason(m)}">${busy}</span>`;let ready=matchReadiness(m);if(!ready.ok)return `<span class="court-locked" title="${ready.reason}">À définir</span>`;let selected=selectedPlanningMatch&&selectedPlanningMatch.comp===m.comp&&selectedPlanningMatch.id===m.id;let cls=m.court?'court-assigned':'court-empty';let txt=m.court?'T'+m.court:'Choisir';let warnings=!m.court?restBetweenMatchesWarnings(m):[];let warnHtml=warnings.length?`<span class="rest-warning-inline">${warnings.map(w=>`⚠ ${teamCode(m.comp,w.id)} : ${w.wait} min`).join('<br>')}</span>`:'';let title=warnings.length?warnings.map(w=>`Temps entre 2 matchs : ${w.wait} min / valeur : ${w.min} min / équipe : ${teamCode(m.comp,w.id)}`).join('\n'):(selected?'Match sélectionné':'Cliquer pour sélectionner ce match');return `<span class="${cls} ${warnings.length?'rest-warning-choice':''}" onclick="selectPlanningMatch('${m.comp}',${m.id})" title="${title}">${txt}${warnHtml}</span>`}  
function isMatchAvailableForTeam(m,key,id){if(!m||m.comp!==key||m.done||Number.isFinite(m.court))return false;let r=matchTeamsResolved(m);if(!r.teams.includes(id))return false;return matchReadiness(m).ok}
function availableMatchesForTeam(key,id){return globalSequence().filter(m=>isMatchAvailableForTeam(m,key,id))}
function lastFinishedAtForTeam(key,id){let times=getAllMatches(key).filter(m=>m.done&&m.endedAt&&matchTeamsResolved(m).teams.includes(id)).map(m=>m.endedAt);return times.length?Math.max(...times):null}
function waitMinutesFrom(ts){if(!ts)return null;return Math.max(0,Math.round((Date.now()-ts)/60000))}
function waitingEntries(key){return Object.values(state[key].teams).map(t=>{let available=availableMatchesForTeam(key,t.id);let last=lastFinishedAtForTeam(key,t.id);let base=last;if(t.waitResetAt)base=base?Math.max(base,t.waitResetAt):t.waitResetAt;let wait=waitMinutesFrom(base);return{team:t,available,last:base,wait}}).filter(x=>x.available.length>0&&x.wait!==null&&!teamHasAbsent(key,x.team.id)).sort((a,b)=>b.wait-a.wait).slice(0,5)}  
function selectWaitingTeamHighlight(comp,id,event){if(event){event.stopPropagation()}highlightedTeam={comp:comp,id:id};highlightedAvailableOnly=true;renderAll(false)}
function waitingTop10Table(key,title){let rows=waitingEntries(key).map((e,i)=>`<tr><td style="text-align:center">${i+1}</td><td><span class="waiting-team" onclick="selectWaitingTeamHighlight('${key}',${e.team.id},event)" title="Surligner les matchs disponibles à réaliser">${teamLabel(key,e.team.id)}</span><div class="small">${e.available.length} match(s) disponible(s)</div></td><td class="waiting-time">${e.wait} min</td></tr>`).join('');return `<h4>TOP5 attente ${title}</h4>${rows?`<table class="waiting-table"><tr><th>#</th><th>Equipe</th><th>Attente</th></tr>${rows}</table>`:`<div class="waiting-empty">Aucune équipe en attente mesurable.</div>`}`}  
function courtsPanel(){let data=availableCourts(),sel=selectedPlanningMatchObj(),items='';data.courts.forEach(c=>{let occupying=globalSequence().find(m=>!m.done&&m.court===c.court);if(c.available){items+=`<button class="court-choice" onclick="assignCourtFromPanel(${c.court})" ${sel&&!sel.done?'':'disabled'}>Terrain ${c.court}<br><small>Libre</small></button>`}else{items+=`<span class="court-unavailable">Terrain ${c.court}<br><small>Occupé${occupying?` - ${occupying.comp.toUpperCase()} ${occupying.id}`:''}</small></span>`}});let selectedText=sel&&!sel.done?`Match sélectionné : <b>${sel.comp.toUpperCase()} ${sel.id}</b>`:'Aucun match sélectionné';return `<div class="court-panel"><h3>Liste des terrains</h3><div class="small">${selectedText}</div><div class="court-grid">${items}</div>${sel&&!sel.done&&sel.court?`<button class="secondary" style="margin-top:8px;width:100%" onclick="clearCourtSelection('${sel.comp}',${sel.id})">Retirer le terrain</button>`:''}<div class="waiting-panel"><h3>Temps d'attente équipes</h3>${waitingTop10Table('dm','DM')}${waitingTop10Table('dh','DH')}</div></div>`}  
function selectTeamHighlight(comp,id,event){if(event){event.stopPropagation()}if(!id)return;highlightedTeam={comp:comp,id:id};highlightedAvailableOnly=false;renderAll(false)}  
function clearTeamHighlight(){if(highlightedTeam){highlightedTeam=null;highlightedAvailableOnly=false;renderAll(false)}}  
function matchContainsHighlightedTeam(m){if(!highlightedTeam||m.comp!==highlightedTeam.comp)return false;let a=resolveSeed(m.comp,m.a),b=resolveSeed(m.comp,m.b);let contains=a===highlightedTeam.id||b===highlightedTeam.id;if(!contains)return false;return highlightedAvailableOnly?isMatchAvailableForTeam(m,highlightedTeam.comp,highlightedTeam.id):true}  
function planningTeamCell(m,side){let seed=side===0?m.a:m.b,id=resolveSeed(m.comp,seed),cls=teamWinnerClass(m,side)+(id?' planning-team-click':'');let click=id?` onclick="selectTeamHighlight('${m.comp}',${id},event)" title="Cliquer pour surligner tous les matchs de cette équipe"`:'';return `<td class="${cls}"${click}>${teamLabel(m.comp,seed)}</td>`}
function matchDurationMinutes(m){if(!m||!m.startedAt)return null;let end=m.endedAt||(m.done?Date.now():Date.now());let mins=Math.round((end-m.startedAt)/60000);return Math.max(0,mins)}
function matchDurationLabel(m){let mins=matchDurationMinutes(m);if(mins===null)return `<span class="duration-empty">-</span>`;if(m.done)return `<span class="duration-cell">${mins} min</span>`;return `<span class="duration-cell duration-running">⏱ ${mins} min</span>`}
function matchLaunchTimeLabel(m){if(!m||!m.startedAt)return `<span class="launch-time-empty">-</span>`;let d=new Date(m.startedAt);return `<span class="launch-time-cell">${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}</span>`}
function completedDurations(key){return getAllMatches(key).filter(m=>m.done&&m.startedAt&&m.endedAt).map(m=>Math.max(0,Math.round((m.endedAt-m.startedAt)/60000)))}
function avgDurationLabel(key){let arr=completedDurations(key);if(!arr.length)return '-';let avg=Math.round(arr.reduce((a,b)=>a+b,0)/arr.length);return `${avg} min`}
function avgDurationGlobalLabel(){let arr=[...completedDurations('dm'),...completedDurations('dh')];if(!arr.length)return '-';let avg=Math.round(arr.reduce((a,b)=>a+b,0)/arr.length);return `${avg} min`}
function setPlanningFilter(mode){planningFilter=mode;renderPlanning()}
function planningFilterLabel(){return planningFilter==='current'?'Matchs en cours':planningFilter==='possible'?'Matchs possibles':'Planning complet'}
function isPlanningMatchVisible(m){if(!matchesPlanningSearch(m))return false;if(planningFilter==='current')return !m.done&&Number.isFinite(m.court);if(planningFilter==='possible')return !m.done&&!Number.isFinite(m.court)&&matchReadiness(m).ok;return true}  
function planningFilterButtons(){let btn=(mode,label)=>`<button class="secondary filter-btn ${planningFilter===mode?'active':''}" onclick="setPlanningFilter('${mode}')">${label}</button>`;return `<div class="planning-filter-bar">${btn('current','Matchs en cours')}${btn('possible','Matchs possibles')}${btn('all','Planning complet')}<span class="small">Vue active : <b>${planningFilterLabel()}</b></span></div>`}
function renderPlanning(){updateSchedule();let seq=globalSequence();let visibleSeq=seq.filter(isPlanningMatchVisible);let rows='';let lastRot='';visibleSeq.forEach(m=>{let selected=selectedPlanningMatch&&selectedPlanningMatch.comp===m.comp&&selectedPlanningMatch.id===m.id;if(m.rotation!==lastRot){rows+=`<tr class="phase-sep"><td colspan="12">${m.rotation} - ${m.time} - ${m.phase}</td></tr>`;lastRot=m.rotation}rows+=`<tr class="${m.done?'match-done':''} ${selected?'selected-planning-match':''} ${matchContainsHighlightedTeam(m)?'team-highlight':''} ${matchHasAbsent(m)?'absent-team':''} ${isKOLockedByPools(m)?'ko-locked':''}"><td>${m.id}</td><td>${m.comp.toUpperCase()}</td>${planningTeamCell(m,0)}${planningTeamCell(m,1)}<td>${m.done?'OK':''}</td><td>${m.phase}</td><td>${m.time}</td><td>${m.rotation}</td><td>${courtSlot(m)}</td><td>${scoreInputs(m)}</td><td class="launch-time-col">${matchLaunchTimeLabel(m)}</td><td class="duration-col">${matchDurationLabel(m)}</td></tr>`});if(!rows){rows=`<tr><td colspan="12" class="calc">Aucun match à afficher pour le filtre « ${planningFilterLabel()} ».</td></tr>`}let durationKpis=`<div class="kpi"><span>Durée moy. DM</span><br><strong>${avgDurationLabel('dm')}</strong></div><div class="kpi"><span>Durée moy. DH</span><br><strong>${avgDurationLabel('dh')}</strong></div><div class="kpi"><span>Durée moy. globale</span><br><strong>${avgDurationGlobalLabel()}</strong></div>`;document.getElementById('planning').innerHTML=`${tournamentSubMenu('planning')}<div class="card planning-sticky-header"><h2>Planning GLOBAL 32+16 - affectation des terrains</h2><div class="row"><label>Heure début <input type="time" value="${state.settings.start}" onchange="state.settings.start=this.value;renderAll(false)"></label><label>Rotation <input type="number" min="5" value="${state.settings.rotation}" onchange="state.settings.rotation=+this.value;renderAll(false)"> min</label><label>Terrains disponibles <input type="number" min="1" max="30" value="${state.settings.courts}" onchange="state.settings.courts=+this.value;selectedPlanningMatch=null;renderAll(false)"></label><label>Temps min. entre 2 matchs <input class="rest-input" type="number" min="0" step="1" value="${minRestBetweenMatches()}" onchange="state.settings.minRestBetweenMatches=+this.value||0;renderAll(false)"> min</label><label class="planning-search-label">🔎 Filtrer équipe <input class="planning-search" type="search" placeholder="Nom, DM-12, DH-04..." value="${esc(planningSearch)}" oninput="planningSearch=this.value;renderPlanning()"></label>${durationKpis}</div>${planningFilterButtons()}</div><div class="planning-layout"><div class="card wide planning-main"><table class="excel"><tr><th class="compact-col">N°</th><th>Compétition</th><th class="planning-team-col">Equipe 1</th><th class="planning-team-col">Equipe 2</th><th class="compact-col">Match OK</th><th>Phase</th><th class="compact-col">Heure estim.</th><th class="compact-col">Rotation</th><th class="compact-col">Terrain</th><th class="planning-score-col">Scores</th><th class="launch-time-col">Heure lancement</th><th class="duration-col">Durée du match</th></tr>${rows}</table></div>${courtsPanel()}</div>`;let el=document.querySelector('.planning-search');if(el&&planningSearch){el.focus();el.setSelectionRange(el.value.length,el.value.length)}}      
function orderedPoolMatches(key){let comp=state[key],ordered=[];for(let r=0;r<6;r++){comp.pools.forEach((p,pi)=>{let m=comp.matches[pi*6+r];if(m)ordered.push(m)})}return ordered}  
function koByIdsForComp(key,ids){return ids.map(id=>state[key].ko.find(m=>m.id===id)).filter(Boolean)}  
function orderedKOMatches(key){if(key==='dm'){return koByIdsForComp('dm',[49,50,51,52,53,54,55,56,65,66,67,68,69,70,71,72,57,58,59,60,73,74,75,76,61,62,77,78,63,64,79,80])}return koByIdsForComp('dh',[124,125,126,127,132,133,134,135,128,129,136,137,130,131,138,139])}  
function schedulingPhases(){return [{name:'Poules',dm:orderedPoolMatches('dm'),dh:orderedPoolMatches('dh')},{name:'Tableaux',dm:orderedKOMatches('dm'),dh:orderedKOMatches('dh')}]}  
function targetByRatio(courts){let total=state.dm.teamCount+state.dh.teamCount;let dmTarget=Math.round(courts*state.dm.teamCount/total);dmTarget=Math.max(1,Math.min(courts-1,dmTarget));return{dm:dmTarget,dh:courts-dmTarget}}  
function symbolicDependencyKeys(key,seed){return typeof seed==='string'?[key+':seed:'+seed]:[]}  
function matchTeamKeys(m){let a=resolveSeed(m.comp,m.a),b=resolveSeed(m.comp,m.b),keys=[];if(a)keys.push(m.comp+':team:'+a);else keys.push(...symbolicDependencyKeys(m.comp,m.a));if(b)keys.push(m.comp+':team:'+b);else keys.push(...symbolicDependencyKeys(m.comp,m.b));return keys}  
function canPlaceInRotation(m,used){return matchTeamKeys(m).every(k=>!used.has(k))}  
function addToRotation(m,used){matchTeamKeys(m).forEach(k=>used.add(k))}  
function pickFromQueue(queue,used){let idx=queue.findIndex(m=>canPlaceInRotation(m,used));if(idx<0)return null;return queue.splice(idx,1)[0]}  
function buildRotation(dmQueue,dhQueue,courts){let target=targetByRatio(courts),used=new Set(),placed=[],count={dm:0,dh:0};let pattern=[];for(let i=0;i<courts;i++){pattern.push((i+1)%3===0?'dh':'dm')}function tryPick(comp){let q=comp==='dm'?dmQueue:dhQueue,m=pickFromQueue(q,used);if(m){placed.push(m);addToRotation(m,used);count[comp]++;return true}return false}for(let pref of pattern){if(placed.length>=courts)break;let other=pref==='dm'?'dh':'dm';let prefLimit=pref==='dm'?target.dm:target.dh;if(count[pref]<prefLimit){if(!tryPick(pref))tryPick(other)}else{if(!tryPick(other))tryPick(pref)}}while(placed.length<courts&&(dmQueue.length||dhQueue.length)){let needDm=count.dm<target.dm,first=needDm?'dm':'dh',second=needDm?'dh':'dm';if(!tryPick(first)&&!tryPick(second))break}return placed}  
function globalSequence(){return plannedSequence.length?plannedSequence:schedulingPhases().flatMap(p=>[...p.dm,...p.dh])}  
function updateSchedule(){let start=parseTime(state.settings.start),rotMin=state.settings.rotation||20,courts=state.settings.courts||9;plannedSequence=[];let rotationIndex=0;schedulingPhases().forEach(phase=>{let dmQueue=[...phase.dm],dhQueue=[...phase.dh];while(dmQueue.length||dhQueue.length){let placed=buildRotation(dmQueue,dhQueue,courts);if(!placed.length){let fallback=dmQueue.shift()||dhQueue.shift();if(fallback)placed=[fallback]}placed.forEach((m,i)=>{m.rotation='R'+(rotationIndex+1);m.court=(!isKOLockedByPools(m)&&Number.isFinite(m.manualCourt)&&m.manualCourt>=1&&m.manualCourt<=courts)?m.manualCourt:null;m.time=formatTime(start+rotationIndex*rotMin);plannedSequence.push(m)});rotationIndex++}})}    
function parseTime(t){let [h,m]=t.split(':').map(Number);return h*60+m} function formatTime(mins){mins=((mins%1440)+1440)%1440;return String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0')}

function ensureCheckRecord(key,id){let c=state.checkin[key][id]||(state.checkin[key][id]={});['present1','present2','absent1','absent2','paid1','paid2'].forEach(f=>{if(typeof c[f]!=='boolean')c[f]=false});if(!c.present1&&!c.absent1)c.absent1=true;if(!c.present2&&!c.absent2)c.absent2=true;if(c.present1){c.absent1=false;c.paid1=true}if(c.present2){c.absent2=false;c.paid2=true}return c}  
function participantFee(){let v=parseFloat(state.settings.participantFee??0);return Number.isFinite(v)?v:0}
function euro(v){return v.toLocaleString('fr-FR',{style:'currency',currency:'EUR'})}
function paidParticipantCount(){return ['dm','dh'].reduce((a,k)=>a+Object.keys(state[k].teams).reduce((b,id)=>{let c=ensureCheckRecord(k,id);return b+(c.paid1?1:0)+(c.paid2?1:0)},0),0)}
function presentParticipantCount(){return ['dm','dh'].reduce((a,k)=>a+Object.keys(state[k].teams).reduce((b,id)=>{let c=ensureCheckRecord(k,id);return b+(c.present1?1:0)+(c.present2?1:0)},0),0)}
function participantName(t,n){let v=n===1?t.j1:t.j2;return esc(v&&v.trim()?v:`Participant ${n}`)}
function normSearch(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim()}
function teamMatchesEmargementSearch(key,t,term){if(!term)return true;ensureParticipantClubs(t);let code=teamCode(key,t.id);let hay=[code,key.toUpperCase(),t.j1,t.j2,t.club,t.club1,t.club2,teamLabel(key,t.id)].map(normSearch).join(' ');return hay.includes(term)}  
function ensureParticipantClubs(t){if(!t)return t;if(t.club1===undefined)t.club1=t.club||'';if(t.club2===undefined)t.club2=t.club||'';return t}
function syncLegacyClub(t){ensureParticipantClubs(t);let vals=[t.club1,t.club2].map(x=>String(x||'').trim()).filter(Boolean);t.club=[...new Set(vals)].join(' / ')}
function participantClub(t,n){ensureParticipantClubs(t);let v=n===1?t.club1:t.club2;return esc(v&&String(v).trim()?v:'')}
function editTeamFromEmargement(key,id,field,value){let t=state[key].teams[id];if(!t)return;ensureParticipantClubs(t);t[field]=value;if(field==='club1'||field==='club2')syncLegacyClub(t);localStorage.setItem(STORAGE,JSON.stringify(state))}  
function renderEmargement(){let fee=participantFee(),paidCount=paidParticipantCount(),presentCount=presentParticipantCount(),total=paidCount*fee,term=normSearch(emargementSearch);let block=(key,title)=>{let allTeams=Object.values(state[key].teams).sort((a,b)=>a.pool.localeCompare(b.pool)||a.pos-b.pos),filtered=allTeams.filter(t=>teamMatchesEmargementSearch(key,t,term));let rows=filtered.map(t=>{ensureParticipantClubs(t);let c=ensureCheckRecord(key,t.id);let code=teamCode(key,t.id),teamAbsent=teamHasAbsent(key,t.id);let lock1=c.present1?'disabled title="Participant présent : modification verrouillée"':'title="Modifier le club du participant 1"';let lock2=c.present2?'disabled title="Participant présent : modification verrouillée"':'title="Modifier le club du participant 2"';let pLock1=c.present1?'disabled title="Participant présent : modification verrouillée"':'title="Modifier le participant 1"';let pLock2=c.present2?'disabled title="Participant présent : modification verrouillée"':'title="Modifier le participant 2"';return `<tr class="${teamAbsent?'absent-team':''}"><td rowspan="2"><b>${code}</b><br><span class="small">Poule ${t.pool} - Rang ${t.pos}</span></td><td><input class="emargement-edit club-edit" type="text" value="${participantClub(t,1)}" ${lock1} onchange="editTeamFromEmargement('${key}',${t.id},'club1',this.value);renderAll(false)"></td><td><input class="emargement-edit participant-edit" type="text" value="${esc(t.j1)}" placeholder="Participant 1" ${pLock1} onchange="editTeamFromEmargement('${key}',${t.id},'j1',this.value);renderAll(false)"></td><td><input type="checkbox" ${c.present1?'checked':''} onchange="checkEdit('${key}',${t.id},'present1',this.checked)"></td><td><input type="checkbox" ${c.absent1?'checked':''} onchange="checkEdit('${key}',${t.id},'absent1',this.checked)"></td><td><input type="checkbox" ${c.paid1?'checked':''} onchange="checkEdit('${key}',${t.id},'paid1',this.checked)"></td></tr><tr class="${teamAbsent?'absent-team':''}"><td><input class="emargement-edit club-edit" type="text" value="${participantClub(t,2)}" ${lock2} onchange="editTeamFromEmargement('${key}',${t.id},'club2',this.value);renderAll(false)"></td><td><input class="emargement-edit participant-edit" type="text" value="${esc(t.j2)}" placeholder="Participant 2" ${pLock2} onchange="editTeamFromEmargement('${key}',${t.id},'j2',this.value);renderAll(false)"></td><td><input type="checkbox" ${c.present2?'checked':''} onchange="checkEdit('${key}',${t.id},'present2',this.checked)"></td><td><input type="checkbox" ${c.absent2?'checked':''} onchange="checkEdit('${key}',${t.id},'absent2',this.checked)"></td><td><input type="checkbox" ${c.paid2?'checked':''} onchange="checkEdit('${key}',${t.id},'paid2',this.checked)"></td></tr>`}).join('');let resultInfo=term?`${filtered.length} équipe(s) trouvée(s) sur ${allTeams.length}`:`${allTeams.length} équipe(s)`;return `<div class="card wide"><h2>${title}</h2><div class="small search-result-count">${resultInfo}</div><table class="excel"><tr><th>Equipe</th><th>Club</th><th>Participant</th><th>Présent</th><th>Absent</th><th>Cotisation payée</th></tr>${rows||`<tr><td colspan="6" class="calc">Aucun résultat</td></tr>`}</table></div>`};document.getElementById('emargement').innerHTML=`${tournamentSubMenu('emargement')}<div class="card emargement-sticky-header"><h2>Emargement 32+16</h2><div class="row"><label>Cotisation par participant <input type="number" min="0" step="0.5" value="${fee}" onchange="state.settings.participantFee=+this.value||0;renderAll(false)"> €</label><label class="emargement-search-label">🔎 Rechercher un joueur / équipe <input class="emargement-search" type="search" placeholder="Nom, club, DM-12, DH-04..." value="${esc(emargementSearch)}" oninput="emargementSearch=this.value;renderEmargement()"></label><div class="kpi"><span>Participants présents</span><br><strong>${presentCount}/96</strong></div><div class="kpi"><span>Paiements reçus</span><br><strong>${paidCount}</strong><div>participants</div></div><div class="kpi"><span>Montant total reçu</span><br><strong>${euro(total)}</strong></div></div><div class="small" style="margin-top:8px">Chaque participant dispose de son propre club. Par défaut, les participants sont absents et les champs Club / Participant sont modifiables. Dès qu’un participant est marqué présent, ses champs deviennent non modifiables.</div></div><div class="layout">${block('dm','32 Equipes - DM')}${block('dh','16 Equipes - DH')}</div>`;let el=document.querySelector('.emargement-search');if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length)}}  
function checkEdit(key,id,field,val){let c=ensureCheckRecord(key,id);c[field]=val;if(field==='present1'&&val){c.absent1=false;c.paid1=true}if(field==='present2'&&val){c.absent2=false;c.paid2=true}if(field==='absent1'&&val){c.present1=false;c.paid1=false;releaseCourtsForTeam(key,id)}if(field==='absent2'&&val){c.present2=false;c.paid2=false;releaseCourtsForTeam(key,id)}if((field==='paid1'&&!val&&c.present1)||(field==='paid2'&&!val&&c.present2)){alert('Cotisation obligatoire : un participant marqué présent doit avoir sa cotisation payée cochée.');c[field]=true}selectedPlanningMatch=null;highlightedAvailableOnly=false;renderAll(false)}  

function tournamentSubMenu(active='dashboard'){let b=(id,label)=>`<button class="tournament-nav-btn ${active===id?'active':''}" onclick="switchTab('${id}')">${label}</button>`;let home=isFullAccess()?`<button class="tournament-nav-btn home" onclick="backHome()">🏠 Accueil</button>`:'';return `<div class="card tournament-submenu">${home}${b('dashboard','📊 Tableau de bord')}${b('dm','🏸 Tournoi DM')}${b('dh','🏸 Tournoi DH')}${b('planning','📅 Planning')}${b('emargement','✅ Emargement')}</div>`}

function renderDashboard(){updateSchedule();let total=[...getAllMatches('dm'),...getAllMatches('dh')], done=total.filter(m=>m.done).length;let present=presentParticipantCount();let paid=paidParticipantCount();document.getElementById('dashboard').innerHTML=`${tournamentSubMenu('dashboard')}<div class="card"><h2>Gestion Tournoi - Tableau de bord</h2><div class="row"><div class="kpi"><span>Matchs joués</span><br><strong>${done}/${total.length}</strong></div><div class="kpi"><span>Participants présents</span><br><strong>${present}/96</strong></div><div class="kpi"><span>Paiements reçus</span><br><strong>${paid}/96</strong></div><div class="kpi"><span>Début / rotation</span><br><strong>${state.settings.start}</strong><div>${state.settings.rotation} min</div></div></div></div><div class="card notice"><b>Mode autonome :</b> ce fichier fonctionne hors ligne dans un navigateur. Les données sont conservées dans le stockage local du navigateur après sauvegarde. Utilisez l'export JSON pour faire une copie de sécurité ou changer de PC.</div><div class="card"><h2>Mode d'emploi rapide</h2><ol><li>Renseigner les équipes dans les onglets DM et DH : les équipes sont identifiées partout par compétition + numéro, par exemple DM-01 ou DH-01.</li><li>Valider les présences/paiements dans l'onglet Emargement.</li><li>Régler l'heure de début, la durée de rotation et le nombre de terrains disponibles dans le Planning global.</li><li>Saisir les scores : le classement des poules et les tableaux se recalculent automatiquement.</li><li>Imprimer le planning, les poules ou l'émargement si besoin.</li></ol></div>`}

const COLUMN_WIDTHS_STORAGE='tbk_column_widths_v41';
function getColumnWidths(){try{return JSON.parse(localStorage.getItem(COLUMN_WIDTHS_STORAGE)||'{}')}catch(e){return {}}}
function setColumnWidths(v){localStorage.setItem(COLUMN_WIDTHS_STORAGE,JSON.stringify(v))}
function getTableAutoFitKey(table){if(!table)return'';if(!table.dataset.autofitId){let page=table.closest('.page'),tables=Array.from((page||document).querySelectorAll('table.excel')),idx=tables.indexOf(table),cls=(table.className||'excel').trim().replace(/\s+/g,'.');table.dataset.autofitId=`${page?page.id:'page'}:${cls}:${idx}`}return table.dataset.autofitId}
function initAutoFitTables(){document.querySelectorAll('table.excel').forEach(t=>getTableAutoFitKey(t))}
function cellsForColumn(table,col){return Array.from(table.rows).map(r=>r.cells[col]).filter(Boolean)}
function measureCellContentWidth(cell){let cs=getComputedStyle(cell),txt=(cell.innerText||cell.textContent||'').replace(/\s+/g,' ').trim();let box=document.createElement('div');box.style.position='absolute';box.style.visibility='hidden';box.style.whiteSpace='nowrap';box.style.left='-9999px';box.style.top='-9999px';box.style.font=cs.font;box.style.fontWeight=cs.fontWeight;box.style.fontSize=cs.fontSize;box.style.fontFamily=cs.fontFamily;box.textContent=txt||' ';document.body.appendChild(box);let w=box.offsetWidth;box.remove();let pad=(parseFloat(cs.paddingLeft)||0)+(parseFloat(cs.paddingRight)||0)+22;let childMax=0;cell.querySelectorAll('input,select,button,textarea,.badge').forEach(el=>{childMax=Math.max(childMax,el.scrollWidth||el.offsetWidth||0)});return Math.ceil(Math.max(w+pad,childMax+pad,cell.scrollWidth||0))}
function applyColumnWidth(table,col,width){let px=Math.max(24,Math.min(width,1200));let cg=table.querySelector('colgroup');if(cg&&cg.children[col])cg.children[col].style.width=px+'px';cellsForColumn(table,col).forEach(c=>{c.style.width=px+'px';c.style.minWidth=px+'px';c.style.maxWidth=px+'px';c.classList.add('column-autofit-flash');setTimeout(()=>c.classList.remove('column-autofit-flash'),500)})}
function autoFitColumn(table,col,saveIt=true){if(!table||col<0)return;let cells=cellsForColumn(table,col);if(!cells.length)return;cells.forEach(c=>{c.style.width='';c.style.minWidth='';c.style.maxWidth=''});let width=Math.max(...cells.map(measureCellContentWidth));applyColumnWidth(table,col,width);if(saveIt){let all=getColumnWidths(),key=getTableAutoFitKey(table);all[key]=all[key]||{};all[key][col]=width;setColumnWidths(all)}}
function applySavedColumnWidths(){initAutoFitTables();let all=getColumnWidths();document.querySelectorAll('table.excel').forEach(t=>{let key=getTableAutoFitKey(t),w=all[key]||{};Object.keys(w).forEach(col=>applyColumnWidth(t,+col,+w[col]))})}
function bindColumnAutoFit(){if(window.__tbkColumnAutoFitBound)return;window.__tbkColumnAutoFitBound=true;document.addEventListener('dblclick',function(e){let cell=e.target.closest('table.excel th,table.excel td');if(!cell)return;let table=cell.closest('table.excel');if(!table)return;autoFitColumn(table,cell.cellIndex,true);e.preventDefault();e.stopPropagation()},true)}
bindColumnAutoFit();



const AUTH_USERS=[
  {login:'admin',password:'admin',role:'administrateur',label:'Administrateur'},
  {login:'bureau',password:'bureau',role:'bureau',label:'Bureau'},
  {login:'tournoi',password:'tournoi',role:'tournoi',label:'Tournoi'}
];
const AUTH_STORAGE='tbk_auth_user';
function currentUser(){try{return JSON.parse(sessionStorage.getItem(AUTH_STORAGE)||'null')}catch(e){return null}}
function isFullAccess(){let u=currentUser();return !!u&&(u.role==='administrateur'||u.role==='bureau')}
function isTournamentRole(){let u=currentUser();return !!u&&u.role==='tournoi'}
function allowedTabsForUser(){if(isFullAccess())return ['portal','inscriptions','dashboard','dm','dh','planning','emargement'];if(isTournamentRole())return ['dashboard','dm','dh','planning','emargement'];return ['login']}
function defaultTabForUser(){return isTournamentRole()?'dashboard':'portal'}
function canAccessTab(tabId){if(tabId==='login')return !currentUser();return allowedTabsForUser().includes(tabId)}
function loginTBK(){let login=(document.getElementById('loginUser')?.value||'').trim().toLowerCase(),password=document.getElementById('loginPassword')?.value||'',msg=document.getElementById('loginMessage');let found=AUTH_USERS.find(u=>u.login===login&&u.password===password);if(!found){if(msg)msg.textContent='Identifiant ou mot de passe incorrect.';return}sessionStorage.setItem(AUTH_STORAGE,JSON.stringify({login:found.login,role:found.role,label:found.label,connectedAt:Date.now()}));updateAuthChrome();renderLogin();switchTab(defaultTabForUser())}
function logoutTBK(){sessionStorage.removeItem(AUTH_STORAGE);updateAuthChrome();renderLogin();switchTab('login')}
function renderLogin(){let el=document.getElementById('login');if(!el)return;el.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">🏸 TBK</div><h1>Connexion au site club</h1><p>Connecte-toi pour accéder aux espaces autorisés.</p><label>Identifiant<input id="loginUser" type="text" autocomplete="username" placeholder="admin, bureau ou tournoi" onkeydown="if(event.key==='Enter')document.getElementById('loginPassword').focus()"></label><label>Mot de passe<input id="loginPassword" type="password" autocomplete="current-password" placeholder="Mot de passe" onkeydown="if(event.key==='Enter')loginTBK()"></label><button class="login-btn" onclick="loginTBK()">Se connecter</button><div id="loginMessage" class="login-error"></div><div class="login-help"><b>Profils disponibles :</b><br>Administrateur et bureau : accès complet.<br>Tournoi : accès uniquement à Gestion Tournoi.</div></div></div>`}

function toolbarButtonsForUser(){let u=currentUser();if(!u)return [];let prof=userProfile(u.role);return Array.isArray(prof.toolbarButtons)?prof.toolbarButtons:defaultToolbarRights(u.role)}
function canAccessToolbarButton(id){return !!currentUser()&&toolbarButtonsForUser().includes(id)}
function updateToolbarRights(){let u=currentUser();document.querySelectorAll('[data-toolbar]').forEach(el=>{let id=el.getAttribute('data-toolbar');let ok=!!u&&canAccessToolbarButton(id);el.hidden=!ok;el.style.display=ok?'inline-flex':'none';el.setAttribute('aria-hidden',ok?'false':'true')});document.body.classList.toggle('toolbar-rights-applied',!!u)}
function updateAuthChrome(){let u=currentUser();document.body.classList.toggle('is-authenticated',!!u);document.body.classList.toggle('role-tournoi',!!u&&u.role==='tournoi');let status=document.getElementById('authStatus');if(status){status.innerHTML=u?`<span class="auth-pill">👤 ${esc(u.label)} <small>${esc(u.role)}</small></span><button class="secondary logout-btn" onclick="logoutTBK()">Déconnexion</button>`:`<span class="auth-pill off">Non connecté</span>`}document.querySelectorAll('.site-main-nav .tab').forEach(btn=>{let allowed=canAccessTab(btn.dataset.tab);btn.style.display=u&&allowed?'inline-flex':'none'});if(!u){document.querySelectorAll('.site-main-nav .tab').forEach(btn=>btn.style.display='none')}else if(isTournamentRole()){document.querySelectorAll('.site-main-nav .tab').forEach(btn=>{btn.style.display=(btn.dataset.tab==='dashboard')?'inline-flex':'none'})};updateToolbarRights()}
function enforceCurrentAccess(){let active=document.querySelector('.page.active');let id=active?active.id:null;if(!currentUser()){switchTab('login');return}if(!id||!canAccessTab(id))switchTab(defaultTabForUser())}

function switchTab(tabId){if(!currentUser()&&tabId!=='login')tabId='login';if(currentUser()&&!canAccessTab(tabId))tabId=defaultTabForUser();document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));let btn=[...document.querySelectorAll('.tab')].find(b=>b.dataset.tab===tabId);if(btn)btn.classList.add('active');let page=document.getElementById(tabId);if(page)page.classList.add('active');updateAuthChrome();window.scrollTo({top:0,behavior:'smooth'})}
function renderPortal(){let total=[...getAllMatches('dm'),...getAllMatches('dh')],done=total.filter(m=>m.done).length,present=presentParticipantCount(),paid=paidParticipantCount();document.getElementById('portal').innerHTML=`<div class="portal-hero site-home-hero"><div><div class="portal-badge">🏸 TBK - Tennis Badminton Kersaint</div><h1>Bienvenue sur le portail du club</h1><p>Cette page est l'accueil du site internet TBK. Choisissez votre espace : suivi des inscriptions 2026-2027 ou gestion des tournois.</p></div><div class="portal-season">TBK<br><span>Club</span></div></div><div class="portal-grid site-home-grid"><button class="portal-card registration-card" onclick="openInscriptionsHome()"><div class="portal-icon">📝</div><h2>Inscriptions 2026-2027</h2><p>Gestion des adhérents, cotisations, licences UFOLEP, WhatsApp, santé, paiements et informations de contact.</p><div class="portal-mini-kpis"><span>Adhérents</span><span>Cotisations</span><span>Licences</span></div><strong>Accéder aux inscriptions →</strong></button><button class="portal-card tournament-card" onclick="openTournamentHome()"><div class="portal-icon">🏆</div><h2>Gestion Tournoi</h2><p>Accès à la gestion des équipes, poules, classements, planning global, scores, émargement et tableaux finaux.</p><div class="portal-mini-kpis"><span>${done}/${total.length} matchs joués</span><span>${present}/96 présents</span><span>${paid}/96 paiements</span></div><strong>Accéder au tournoi →</strong></button></div><div class="card notice site-home-note"><b>Navigation simplifiée :</b> les anciens boutons techniques ne sont plus affichés dans le menu principal. Les écrans détaillés restent accessibles depuis l'espace Gestion Tournoi.</div>`}
function openInscriptionsHome(){switchTab('inscriptions')}
function openTournamentHome(){switchTab('dashboard')}
function backHome(){switchTab(defaultTabForUser())}

function ensureInscriptions(){state.inscriptions=state.inscriptions||[];return state.inscriptions}
const INSC_COLUMNS_STORAGE='tbk_inscription_columns_v50';
function defaultInscriptionColumns(){return [
  {id:'nom',field:'nom',label:'Nom',type:'text',visible:true,builtIn:true},
  {id:'prenom',field:'prenom',label:'Prénom',type:'text',visible:true,builtIn:true},
  {id:'categorie',field:'categorie',label:'Catégorie',type:'select',options:['Jeune','Adulte'],visible:true,builtIn:true},
  {id:'ufolep',field:'ufolep',label:'UFOLEP',type:'yesno',visible:true,builtIn:true},
  {id:'whatsapp',field:'whatsapp',label:'WhatsApp',type:'yesno',visible:true,builtIn:true},
  {id:'sport',field:'sport',label:'Sport',type:'select',options:['Bad','Ping','Bad et Ping'],visible:true,builtIn:true},
  {id:'montantCotisation',field:'montantCotisation',label:'Montant Cotisation',type:'amount',visible:true,builtIn:true},
  {id:'cotisationPayee',field:'cotisationPayee',label:'Cotisation Payée',type:'yesno',visible:true,builtIn:true},
  {id:'sante',field:'sante',label:'Santé',type:'select',options:['Certif Médical','QS Sport'],visible:true,builtIn:true},
  {id:'dateCertif',field:'dateCertif',label:'Date Certif Médical',type:'date',visible:true,builtIn:true},
  {id:'telephone',field:'telephone',label:'N° Téléphone',type:'text',visible:true,builtIn:true,css:'phone-input'},
  {id:'adresse',field:'adresse',label:'Adresse',type:'text',visible:true,builtIn:true,css:'address-input'},
  {id:'mail',field:'mail',label:'Mail',type:'email',visible:true,builtIn:true,css:'mail-input'},
  {id:'dateNaissance',field:'dateNaissance',label:'Date de naissance',type:'date',visible:true,builtIn:true},
  {id:'membreBureau',field:'membreBureau',label:'Membre du Bureau',type:'yesno',visible:true,builtIn:true},
  {id:'action',field:'action',label:'Action',type:'action',visible:true,builtIn:true}
]}
function getInscriptionColumns(){let cols;try{cols=JSON.parse(localStorage.getItem(INSC_COLUMNS_STORAGE)||'null')}catch(e){cols=null}let defs=defaultInscriptionColumns();if(!Array.isArray(cols)){cols=defs}else{let ids=cols.map(c=>c.id);defs.forEach(d=>{if(!ids.includes(d.id))cols.push(d)});cols=cols.map(c=>({...defs.find(d=>d.id===c.id),...c}))}localStorage.setItem(INSC_COLUMNS_STORAGE,JSON.stringify(cols));return cols}
function saveInscriptionColumns(cols){localStorage.setItem(INSC_COLUMNS_STORAGE,JSON.stringify(cols))}
function ensureInscriptionCustomFields(x){x.customFields=x.customFields||{};return x.customFields}
function cellLocked(x){return false}
function disabledAttr(x){return ''}
function addInscriptionDemo(){let arr=ensureInscriptions();arr.push({nom:'',prenom:'',categorie:'Adulte',ufolep:'Non',whatsapp:'Non',sport:'Bad',montantCotisation:'',cotisationPayee:'Non',sante:'QS Sport',dateCertif:'',telephone:'',adresse:'',mail:'',dateNaissance:'',membreBureau:'Non',customFields:{}});renderAll(false);switchTab('inscriptions')}
function updateInscription(i,field,value){let arr=ensureInscriptions();if(!arr[i])return;arr[i][field]=value;renderAll(false);switchTab('inscriptions')}
function updateInscriptionSoft(i,field,value){let arr=ensureInscriptions();if(!arr[i])return;arr[i][field]=value;localStorage.setItem(STORAGE,JSON.stringify(state))}
function updateCustomInscription(i,field,value,soft=false){let arr=ensureInscriptions();if(!arr[i])return;ensureInscriptionCustomFields(arr[i])[field]=value;if(soft)localStorage.setItem(STORAGE,JSON.stringify(state));else{renderAll(false);switchTab('inscriptions')}}
function deleteInscription(i){let arr=ensureInscriptions();if(!arr[i])return;if(!confirm('Supprimer cette inscription ?'))return;arr.splice(i,1);renderAll(false);switchTab('inscriptions')}
function yesNoSelect(value,idx,field,row){let dis=disabledAttr(row);return `<select ${dis} onchange="updateInscription(${idx},'${field}',this.value)"><option ${value==='Oui'?'selected':''}>Oui</option><option ${value!=='Oui'?'selected':''}>Non</option></select>`}
function yesNoCustomSelect(value,idx,field,row){let dis=disabledAttr(row);return `<select ${dis} onchange="updateCustomInscription(${idx},'${field}',this.value)"><option ${value==='Oui'?'selected':''}>Oui</option><option ${value!=='Oui'?'selected':''}>Non</option></select>`}
function ensureInscriptionSettings(){state.inscriptionSettings=state.inscriptionSettings||{};let s=state.inscriptionSettings;if(!Number.isFinite(+s.cotisationAdulte))s.cotisationAdulte=40;if(!Number.isFinite(+s.cotisationJeune))s.cotisationJeune=30;if(!Number.isFinite(+s.supplementBadPing))s.supplementBadPing=10;if(!Number.isFinite(+s.supplementUfolep))s.supplementUfolep=20;if(!Number.isFinite(+s.reductionBureau))s.reductionBureau=10;return s}
function updateInscriptionSetting(field,value){let s=ensureInscriptionSettings();s[field]=Number(value)||0;renderAll(false);switchTab('inscriptions')}
function cotisationCalculee(x){let s=ensureInscriptionSettings();let total=(x.categorie==='Jeune'?+s.cotisationJeune:+s.cotisationAdulte);if(x.sport==='Bad et Ping')total+=(+s.supplementBadPing||0);if(x.ufolep==='Oui')total+=(+s.supplementUfolep||0);if(x.membreBureau==='Oui')total-=(+s.reductionBureau||0);return Math.max(0,total)}
function montantCotisationEffectif(x){let v=x.montantCotisation;if(v!==undefined&&v!==null&&String(v).trim()!==''&&Number.isFinite(+v))return +v;return cotisationCalculee(x)}
function resetCotisationToCalculated(i){let arr=ensureInscriptions();if(!arr[i])return;arr[i].montantCotisation='';renderAll(false);switchTab('inscriptions')}
function statusPaidClass(x){return x.cotisationPayee==='Oui'?'paid-ok':'paid-ko'}
function dateDisplay(v){let s=String(v||'');let m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:s}
function dateToIso(v){let s=String(v||'').trim();let m=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(m)return `${m[3]}-${m[2]}-${m[1]}`;m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?s:''}
function dateMask(el){let d=el.value.replace(/\D/g,'').slice(0,8);if(d.length>4)el.value=d.slice(0,2)+'/'+d.slice(2,4)+'/'+d.slice(4);else if(d.length>2)el.value=d.slice(0,2)+'/'+d.slice(2);else el.value=d}
function normalizeDateValue(v){let d=String(v||'').replace(/\D/g,'').slice(0,8);return d.length===8?d.slice(0,2)+'/'+d.slice(2,4)+'/'+d.slice(4):String(v||'')}
function syncCalendarDate(textId,dateId){let t=document.getElementById(textId),d=document.getElementById(dateId);if(t&&d)d.value=dateToIso(t.value)}
function setDateFromCalendar(i,field,dateInput,textId,custom){let txt=document.getElementById(textId);let val=dateDisplay(dateInput.value);if(txt)txt.value=val;if(custom)updateCustomInscription(i,field,val,true);else updateInscriptionSoft(i,field,val)}
function openDatePicker(id){let el=document.getElementById(id);if(!el)return;if(el.showPicker)el.showPicker();else el.click()}
function renderDateInput(i,field,value,row,custom=false){let textId=`date_txt_${field}_${i}`,dateId=`date_cal_${field}_${i}`,display=dateDisplay(value),dis=disabledAttr(row);return `<div class="date-combo"><input id="${textId}" class="insc-input date-input" type="text" inputmode="numeric" placeholder="JJ/MM/AAAA" maxlength="10" value="${esc(display)}" ${dis} onfocus="syncCalendarDate('${textId}','${dateId}')" oninput="dateMask(this)" onchange="${custom?`updateCustomInscription(${i},'${field}',normalizeDateValue(this.value),true)`: `updateInscriptionSoft(${i},'${field}',normalizeDateValue(this.value))`};syncCalendarDate('${textId}','${dateId}')"><button type="button" class="secondary mini-date-btn" ${dis} onclick="syncCalendarDate('${textId}','${dateId}');openDatePicker('${dateId}')">📅</button><input id="${dateId}" class="hidden-date-input" type="date" value="${dateToIso(display)}" ${dis} onchange="setDateFromCalendar(${i},'${field}',this,'${textId}',${custom})"></div>`}
function renderSelectCell(i,col,x,value,custom=false){let dis=disabledAttr(x),options=col.options||[];if((value===undefined||value===null||String(value).trim()==='')&&options.length===1){value=options[0];if(custom)ensureInscriptionCustomFields(x)[col.field]=value;else x[col.field]=value;localStorage.setItem(STORAGE,JSON.stringify(state))}let opts=options.map(v=>`<option ${value===v?'selected':''}>${esc(v)}</option>`).join('');return `<select ${dis} onchange="${custom?`updateCustomInscription(${i},'${col.field}',this.value)`: `updateInscription(${i},'${col.field}',this.value)`}">${opts}</select>`}
function renderInscriptionCell(i,col,x){let lock=disabledAttr(x),value=col.builtIn?x[col.field]:(ensureInscriptionCustomFields(x)[col.field]||'');if(col.type==='action')return `<td>${cellLocked(x)&&!isAdminUser()?'<span class="locked-badge">🔒 Payée</span>':`<button class="danger" onclick="deleteInscription(${i})">Supprimer</button>`}</td>`;if(col.type==='amount'){let calc=cotisationCalculee(x),cot=montantCotisationEffectif(x),isManual=String(x.montantCotisation??'').trim()!=='';return `<td class="amount-calculated"><div class="amount-editor"><input class="insc-input amount-input" type="number" min="0" step="1" value="${esc(cot)}" ${lock} title="Montant calculé proposé : ${euro(calc)}. Ce montant reste modifiable par l\'administrateur si la ligne est payée." onchange="updateInscriptionSoft(${i},'montantCotisation',this.value)"><button type="button" class="secondary mini-btn" ${lock} title="Revenir au montant calculé ${euro(calc)}" onclick="resetCotisationToCalculated(${i})">↻</button></div><div class="small amount-note">${isManual?'Modifié':'Calculé'} : ${euro(calc)}</div></td>`}
if(col.type==='yesno')return `<td>${col.builtIn?yesNoSelect(value,i,col.field,x):yesNoCustomSelect(value,i,col.field,x)}</td>`;
if(col.type==='select')return `<td>${renderSelectCell(i,col,x,value,!col.builtIn)}</td>`;
if(col.type==='date')return `<td>${renderDateInput(i,col.field,value,x,!col.builtIn)}</td>`;
let inputType=col.type==='email'?'email':'text',css=col.css||'';return `<td><input class="insc-input ${css}" type="${inputType}" value="${esc(value)}" ${lock} onchange="${col.builtIn?`updateInscriptionSoft(${i},'${col.field}',this.value)`: `updateCustomInscription(${i},'${col.field}',this.value,true)`}"></td>`}
function visibleInscriptionColumns(){return getInscriptionColumns().filter(c=>c.visible!==false)}

function splitColumnOptions(value){return String(value||'').split(',').map(x=>x.trim()).filter(Boolean)}
function updateInscriptionColumnOptions(id,value){let cols=getInscriptionColumns();let c=cols.find(x=>x.id===id);if(!c)return;c.options=splitColumnOptions(value);saveInscriptionColumns(cols);renderAll(false);switchTab('inscriptions')}

function renderColumnAdminPanel(){if(!isAdminUser())return '';let cols=getInscriptionColumns();let rows=cols.map((c,i)=>{let editableOptions=c.type==='select';let optionsValue=esc((c.options||[]).join(', '));return `<tr class="${c.visible===false?'column-hidden':''}"><td>${i+1}</td><td><input value="${esc(c.label)}" onchange="renameInscriptionColumn('${c.id}',this.value)"></td><td><span class="small">${esc(c.type)}</span></td><td>${editableOptions?`<input class="column-options-input" value="${optionsValue}" placeholder="Valeur 1, Valeur 2" onchange="updateInscriptionColumnOptions('${c.id}',this.value)">`:'<span class="small muted">-</span>'}</td><td><input type="checkbox" ${c.visible!==false?'checked':''} onchange="toggleInscriptionColumn('${c.id}',this.checked)"></td><td><button class="secondary" onclick="moveInscriptionColumn('${c.id}',-1)">↑</button><button class="secondary" onclick="moveInscriptionColumn('${c.id}',1)">↓</button></td><td>${c.builtIn?`<button class="secondary" onclick="toggleInscriptionColumn('${c.id}',false)">Masquer</button>`:`<button class="danger" onclick="deleteInscriptionColumn('${c.id}')">Supprimer</button>`}</td></tr>`}).join('');return `<div class="card wide column-admin-panel"><h3>Administration des colonnes</h3><div class="small">Profil administrateur uniquement : renommer, masquer/supprimer, ajouter et déplacer les colonnes. Pour les colonnes de type <b>select</b>, les valeurs possibles sont modifiables ci-dessous, séparées par des virgules. Si une seule valeur est indiquée, elle est proposée par défaut.</div><div class="admin-grid compact"><label>Nom nouvelle colonne<input id="newInscColLabel" placeholder="Ex : Remise spéciale"></label><label>Type<select id="newInscColType" onchange="document.getElementById('newInscColOptionsWrap').style.display=this.value==='select'?'block':'none'"><option value="text">Texte</option><option value="yesno">Oui / Non</option><option value="select">Select</option><option value="date">Date</option><option value="number">Nombre</option></select></label><label id="newInscColOptionsWrap" style="display:none">Valeurs possibles<input id="newInscColOptions" placeholder="Valeur 1, Valeur 2, Valeur 3"></label><button onclick="addInscriptionColumn()">➕ Ajouter une colonne</button><button class="secondary" onclick="resetInscriptionColumns()">Réinitialiser colonnes</button></div><table class="excel column-admin-table"><tr><th>Ordre</th><th>Nom colonne</th><th>Type</th><th>Valeurs possibles si select</th><th>Visible</th><th>Déplacer</th><th>Action</th></tr>${rows}</table></div>`}

function renameInscriptionColumn(id,label){let cols=getInscriptionColumns();let c=cols.find(x=>x.id===id);if(c){c.label=label||c.label;saveInscriptionColumns(cols);renderAll(false);switchTab('inscriptions')}}
function toggleInscriptionColumn(id,visible){let cols=getInscriptionColumns();let c=cols.find(x=>x.id===id);if(c){c.visible=visible;saveInscriptionColumns(cols);renderAll(false);switchTab('inscriptions')}}
function moveInscriptionColumn(id,dir){let cols=getInscriptionColumns();let i=cols.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=cols.length)return;[cols[i],cols[j]]=[cols[j],cols[i]];saveInscriptionColumns(cols);renderAll(false);switchTab('inscriptions')}
function addInscriptionColumn(){let label=(document.getElementById('newInscColLabel')?.value||'').trim(),type=document.getElementById('newInscColType')?.value||'text',rawOptions=document.getElementById('newInscColOptions')?.value||'';if(!label)return alert('Nom de colonne obligatoire.');let id='custom_'+Date.now();let col={id,field:id,label,type,visible:true,builtIn:false};if(type==='yesno')col.options=['Oui','Non'];if(type==='select'){let options=splitColumnOptions(rawOptions);if(!options.length)return alert('Pour une colonne de type select, indique au moins une valeur possible.');col.options=options}let cols=getInscriptionColumns();let actionIndex=cols.findIndex(c=>c.id==='action');if(actionIndex>=0)cols.splice(actionIndex,0,col);else cols.push(col);saveInscriptionColumns(cols);renderAll(false);switchTab('inscriptions')}
function deleteInscriptionColumn(id){let cols=getInscriptionColumns();let col=cols.find(c=>c.id===id);if(!col||col.builtIn)return;if(!confirm('Supprimer cette colonne et les valeurs associées ?'))return;cols=cols.filter(c=>c.id!==id);saveInscriptionColumns(cols);ensureInscriptions().forEach(x=>{if(x.customFields)delete x.customFields[id]});renderAll(false);switchTab('inscriptions')}
function resetInscriptionColumns(){if(!confirm('Réinitialiser les colonnes par défaut ? Les colonnes personnalisées seront retirées.'))return;localStorage.removeItem(INSC_COLUMNS_STORAGE);renderAll(false);switchTab('inscriptions')}
function renderInscriptions(){let arr=ensureInscriptions(),set=ensureInscriptionSettings(),cols=visibleInscriptionColumns();arr.forEach(x=>{x.categorie=x.categorie||'Adulte';x.ufolep=x.ufolep||'Non';x.whatsapp=x.whatsapp||'Non';x.sport=x.sport||'Bad';if(x.montantCotisation===undefined)x.montantCotisation='';x.cotisationPayee=x.cotisationPayee||'Non';x.sante=x.sante||'QS Sport';x.dateCertif=dateDisplay(x.dateCertif||'');x.telephone=x.telephone||'';x.adresse=x.adresse||'';x.mail=x.mail||'';x.dateNaissance=dateDisplay(x.dateNaissance||'');x.membreBureau=x.membreBureau||'Non';ensureInscriptionCustomFields(x)});let total=arr.length,adultes=arr.filter(x=>x.categorie==='Adulte').length,jeunes=arr.filter(x=>x.categorie==='Jeune').length,ufolep=arr.filter(x=>x.ufolep==='Oui').length,payes=arr.filter(x=>x.cotisationPayee==='Oui').length,bureau=arr.filter(x=>x.membreBureau==='Oui').length,bad=arr.filter(x=>x.sport==='Bad').length,ping=arr.filter(x=>x.sport==='Ping').length,badping=arr.filter(x=>x.sport==='Bad et Ping').length,montantTotal=arr.reduce((s,x)=>s+montantCotisationEffectif(x),0),encaisse=arr.reduce((s,x)=>s+(x.cotisationPayee==='Oui'?montantCotisationEffectif(x):0),0),reste=Math.max(0,montantTotal-encaisse);let headers=cols.map(c=>`<th>${esc(c.label)}</th>`).join('');let rows=arr.map((x,i)=>`<tr class="${statusPaidClass(x)} ">${cols.map(c=>renderInscriptionCell(i,c,x)).join('')}</tr>`).join('');document.getElementById('inscriptions').innerHTML=`<div class="card module-nav"><button onclick="backHome()">← Retour à l'accueil</button><button onclick="switchTab('dashboard')">🏆 Gestion Tournoi</button></div><div class="card inscriptions-sticky-header"><h2>Suivi inscriptions TBK - Saison 2026-2027</h2><div class="cotisation-settings"><label>Cotisation Adulte <input type="number" min="0" step="1" value="${set.cotisationAdulte}" onchange="updateInscriptionSetting('cotisationAdulte',this.value)"> €</label><label>Cotisation Jeune <input type="number" min="0" step="1" value="${set.cotisationJeune}" onchange="updateInscriptionSetting('cotisationJeune',this.value)"> €</label><label>Suppl. Bad + Ping <input type="number" min="0" step="1" value="${set.supplementBadPing}" onchange="updateInscriptionSetting('supplementBadPing',this.value)"> €</label><label>Suppl. UFOLEP <input type="number" min="0" step="1" value="${set.supplementUfolep}" onchange="updateInscriptionSetting('supplementUfolep',this.value)"> €</label><label>Réduction Bureau <input type="number" min="0" step="1" value="${set.reductionBureau}" onchange="updateInscriptionSetting('reductionBureau',this.value)"> €</label></div><div class="row"><div class="kpi"><span>Total adhérents</span><br><strong>${total}</strong></div><div class="kpi"><span>Adultes / Jeunes</span><br><strong>${adultes}/${jeunes}</strong></div><div class="kpi"><span>UFOLEP</span><br><strong>${ufolep}</strong></div><div class="kpi"><span>Cotisations payées</span><br><strong>${payes}</strong></div><div class="kpi"><span>Cotisations théoriques</span><br><strong>${euro(montantTotal)}</strong></div><div class="kpi"><span>Cotisations encaissées</span><br><strong>${euro(encaisse)}</strong></div><div class="kpi"><span>Reste à percevoir</span><br><strong>${euro(reste)}</strong></div><div class="kpi"><span>Bureau</span><br><strong>${bureau}</strong></div><div class="kpi"><span>Bad/Ping/Mixte</span><br><strong>${bad}/${ping}/${badping}</strong></div><button onclick="addInscriptionDemo()">➕ Ajouter une inscription</button></div><div class="small" style="margin-top:8px">Les données restent toujours modifiables, quel que soit le statut de paiement. Le profil administrateur peut aussi administrer les colonnes.</div></div>${renderColumnAdminPanel()}<div class="card wide"><table class="excel inscriptions-table"><tr>${headers}</tr>${rows||`<tr><td colspan="${cols.length}" class="calc">Aucune inscription enregistrée. Clique sur Ajouter une inscription pour commencer.</td></tr>`}</table></div>`}
function renderAll(skipSave){renderPortal();renderDashboard();renderComp('dm');renderComp('dh');renderPlanning();renderEmargement();renderInscriptions();renderUserAdmin();renderDocumentation();applySavedColumnWidths();if(!skipSave) localStorage.setItem(STORAGE,JSON.stringify(state))}
function esc(s){return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function exportJSON(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='tbk_tournois_sauvegarde.json';a.click();URL.revokeObjectURL(a.href)}
function importJSON(e){let f=e.target.files[0]; if(!f)return;let r=new FileReader();r.onload=()=>{try{state=JSON.parse(r.result);save();renderAll(true)}catch(err){alert('Fichier JSON invalide')}};r.readAsText(f)}
function resetScores(){if(!confirm('Effacer tous les scores ?'))return;[...getAllMatches('dm'),...getAllMatches('dh')].forEach(m=>{m.scores=[[null,null],[null,null],[null,null]];m.done=false;m.winner=null;m.loser=null;delete m.startedAt;delete m.endedAt});renderAll(false)}  
function factoryReset(){if(!confirm('Réinitialiser complètement l application ?'))return;localStorage.removeItem(STORAGE);state=init(defaultState());renderAll(false)}
document.addEventListener('click',function(e){if(!e.target.closest('.planning-team-click')){if(highlightedTeam){highlightedTeam=null;highlightedAvailableOnly=false;renderAll(false)}}});  
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
setInterval(function(){if(document.getElementById('planning').classList.contains('active')){renderPlanning()}},10000);  

function isAdminMode(){return localStorage.getItem('tbk_admin_mode')==='1'}
function toggleAdminMode(){let next=!isAdminMode();localStorage.setItem('tbk_admin_mode',next?'1':'0');updateAdminToolbar()}
function updateAdminToolbar(){let admin=isAdminMode();let b=document.getElementById('adminModeBtn');if(b){b.textContent=admin?'🔐 Mode administrateur':'👤 Mode utilisateur';b.classList.toggle('admin-active',admin);b.title=admin?'Cliquer pour revenir au mode utilisateur':'Cliquer pour passer en mode administrateur'}updateToolbarRights()}


/* ===== V49 - Administration utilisateurs, profils et droits ===== */
const TBK_USERS_STORAGE='tbk_auth_users_v49';
const TBK_PROFILES_STORAGE='tbk_auth_profiles_v49';
const TBK_PAGES=[
  {id:'portal',label:'Accueil'},
  {id:'inscriptions',label:'Inscriptions 2026-2027'},
  {id:'dashboard',label:'Gestion Tournoi - Tableau de bord'},
  {id:'dm',label:'Tournoi DM'},
  {id:'dh',label:'Tournoi DH'},
  {id:'planning',label:'Planning'},
  {id:'emargement',label:'Emargement'},
  {id:'adminUsers',label:'Administration utilisateurs'},
  {id:'documentation',label:'Documentation'}
];

const TBK_TOOLBAR_BUTTONS=[
  {id:'save',label:'💾 Sauvegarder'},
  {id:'exportJSON',label:'⬇️ Export JSON'},
  {id:'importJSON',label:'⬆️ Import JSON'},
  {id:'print',label:'🖨️ Imprimer'},
  {id:'resetScores',label:'♻️ Effacer scores'},
  {id:'factoryReset',label:'Réinitialiser tout'},
  {id:'adminMode',label:'👤 Mode administrateur'}
];
function defaultToolbarRights(role){
  if(role==='administrateur')return TBK_TOOLBAR_BUTTONS.map(b=>b.id);
  if(role==='bureau')return ['save','exportJSON','importJSON','print'];
  if(role==='tournoi')return ['save','print'];
  return ['save','print'];
}
function defaultProfilesV49(){return {
  administrateur:{label:'Administrateur',pages:['portal','inscriptions','dashboard','dm','dh','planning','emargement','adminUsers','documentation'],toolbarButtons:defaultToolbarRights('administrateur')},
  bureau:{label:'Bureau',pages:['portal','inscriptions','dashboard','dm','dh','planning','emargement'],toolbarButtons:defaultToolbarRights('bureau')},
  tournoi:{label:'Tournoi',pages:['dashboard','dm','dh','planning','emargement'],toolbarButtons:defaultToolbarRights('tournoi')}
}}
function defaultUsersV49(){return [
  {login:'admin',label:'Administrateur',password:'admin',role:'administrateur',active:true},
  {login:'bureau',label:'Bureau',password:'bureau',role:'bureau',active:true},
  {login:'tournoi',label:'Tournoi',password:'tournoi',role:'tournoi',active:true}
]}
function ensureAuthConfig(){if(!localStorage.getItem(TBK_PROFILES_STORAGE))localStorage.setItem(TBK_PROFILES_STORAGE,JSON.stringify(defaultProfilesV49()));if(!localStorage.getItem(TBK_USERS_STORAGE))localStorage.setItem(TBK_USERS_STORAGE,JSON.stringify(defaultUsersV49()))}
function getAuthProfiles(){ensureAuthConfig();let profiles;try{profiles=JSON.parse(localStorage.getItem(TBK_PROFILES_STORAGE)||'{}')}catch(e){profiles=defaultProfilesV49()}let defs=defaultProfilesV49(),changed=false;Object.entries(defs).forEach(([id,def])=>{if(!profiles[id]){profiles[id]=def;changed=true}else{if(!Array.isArray(profiles[id].pages)){profiles[id].pages=def.pages||[];changed=true}if(!Array.isArray(profiles[id].toolbarButtons)){profiles[id].toolbarButtons=def.toolbarButtons||defaultToolbarRights(id);changed=true}if(!profiles[id].label){profiles[id].label=def.label||id;changed=true}}});Object.entries(profiles).forEach(([id,p])=>{if(!Array.isArray(p.toolbarButtons)){p.toolbarButtons=defaultToolbarRights(id);changed=true}});if(changed)saveAuthProfiles(profiles);return profiles}
function saveAuthProfiles(p){localStorage.setItem(TBK_PROFILES_STORAGE,JSON.stringify(p))}
function getAuthUsers(){ensureAuthConfig();try{return JSON.parse(localStorage.getItem(TBK_USERS_STORAGE)||'[]')}catch(e){return defaultUsersV49()}}
function saveAuthUsers(u){localStorage.setItem(TBK_USERS_STORAGE,JSON.stringify(u))}
function currentUser(){try{return JSON.parse(sessionStorage.getItem(AUTH_STORAGE)||'null')}catch(e){return null}}
function userProfile(role){let p=getAuthProfiles();return p[role]||{label:role,pages:[],toolbarButtons:defaultToolbarRights(role)}}
function isAdminUser(){let u=currentUser();return !!u&&u.role==='administrateur'}
function isFullAccess(){let u=currentUser();if(!u)return false;let pages=userProfile(u.role).pages||[];return ['portal','inscriptions','dashboard','dm','dh','planning','emargement'].every(x=>pages.includes(x))}
function isTournamentRole(){let u=currentUser();if(!u)return false;let pages=userProfile(u.role).pages||[];return pages.includes('dashboard')&&!pages.includes('inscriptions')&&!pages.includes('portal')}
function allowedTabsForUser(){let u=currentUser();if(!u)return ['login'];return userProfile(u.role).pages||[]}
function defaultTabForUser(){let pages=allowedTabsForUser();if(pages.includes('portal'))return 'portal';if(pages.includes('dashboard'))return 'dashboard';if(pages.includes('inscriptions'))return 'inscriptions';return 'login'}
function canAccessTab(tabId){if(tabId==='login')return !currentUser();return allowedTabsForUser().includes(tabId)}
function loginTBK(){ensureAuthConfig();let login=(document.getElementById('loginUser')?.value||'').trim().toLowerCase(),password=document.getElementById('loginPassword')?.value||'',msg=document.getElementById('loginMessage');let found=getAuthUsers().find(u=>String(u.login).toLowerCase()===login&&u.password===password&&u.active!==false);if(!found){if(msg)msg.textContent='Identifiant ou mot de passe incorrect, ou utilisateur désactivé.';return}let prof=userProfile(found.role);sessionStorage.setItem(AUTH_STORAGE,JSON.stringify({login:found.login,role:found.role,label:found.label||found.login,profileLabel:prof.label,connectedAt:Date.now()}));updateAuthChrome();renderLogin();switchTab(defaultTabForUser())}
function logoutTBK(){sessionStorage.removeItem(AUTH_STORAGE);updateAuthChrome();renderLogin();switchTab('login')}
function renderLogin(){let el=document.getElementById('login');if(!el)return;el.innerHTML=`<div class="login-page"><div class="login-card"><div class="login-logo">🏸 TBK</div><h1>Connexion au site club</h1><p>Connecte-toi pour accéder aux espaces autorisés.</p><label>Identifiant<input id="loginUser" type="text" autocomplete="username" placeholder="admin, bureau ou tournoi" onkeydown="if(event.key==='Enter')document.getElementById('loginPassword').focus()"></label><label>Mot de passe<input id="loginPassword" type="password" autocomplete="current-password" placeholder="Mot de passe" onkeydown="if(event.key==='Enter')loginTBK()"></label><button class="login-btn" onclick="loginTBK()">Se connecter</button><div id="loginMessage" class="login-error"></div><div class="login-help"><b>Profils par défaut :</b><br>Administrateur : accès complet + administration utilisateurs.<br>Bureau : accès club et tournoi.<br>Tournoi : accès uniquement aux pages tournoi.</div></div></div>`}
function updateAuthChrome(){let u=currentUser();document.body.classList.toggle('is-authenticated',!!u);document.body.classList.toggle('role-tournoi',!!u&&isTournamentRole());if(!u){document.querySelectorAll('[data-toolbar]').forEach(el=>{el.hidden=true;el.style.display='none'});}let status=document.getElementById('authStatus');if(status){status.innerHTML=u?`<span class="auth-pill">👤 ${esc(u.label)} <small>${esc(userProfile(u.role).label||u.role)}</small></span><button class="secondary logout-btn" onclick="logoutTBK()">Déconnexion</button>`:`<span class="auth-pill off">Non connecté</span>`}document.querySelectorAll('.site-main-nav .tab').forEach(btn=>{btn.style.display=(u&&canAccessTab(btn.dataset.tab))?'inline-flex':'none'});updateToolbarRights()}
function enforceCurrentAccess(){let active=document.querySelector('.page.active'),id=active?active.id:null;if(!currentUser()){switchTab('login');return}if(!id||!canAccessTab(id))switchTab(defaultTabForUser())}
function switchTab(tabId){if(!currentUser()&&tabId!=='login')tabId='login';if(currentUser()&&!canAccessTab(tabId))tabId=defaultTabForUser();document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));let btn=[...document.querySelectorAll('.tab')].find(b=>b.dataset.tab===tabId);if(btn)btn.classList.add('active');let page=document.getElementById(tabId);if(page)page.classList.add('active');if(tabId==='adminUsers')renderUserAdmin();if(tabId==='documentation')renderDocumentation();updateAuthChrome();window.scrollTo({top:0,behavior:'smooth'})}
function renderPortal(){let total=[...getAllMatches('dm'),...getAllMatches('dh')],done=total.filter(m=>m.done).length,present=presentParticipantCount(),paid=paidParticipantCount();let documentationCard=canAccessTab('documentation')?`<button class="portal-card admin-card" onclick="switchTab('documentation')"><div class="portal-icon">📚</div><h2>Documentation</h2><p>Consulter la documentation utilisateur détaillée et les règles de gestion du site.</p><div class="portal-mini-kpis"><span>Règles</span><span>Droits</span><span>Procédures</span></div><strong>Ouvrir la documentation →</strong></button>`:'';let adminCard=isAdminUser()?`<button class="portal-card admin-card" onclick="switchTab('adminUsers')"><div class="portal-icon">🔐</div><h2>Administration utilisateurs</h2><p>Ajouter des utilisateurs, définir des profils, gérer les droits d'accès aux pages et réinitialiser les mots de passe.</p><div class="portal-mini-kpis"><span>Utilisateurs</span><span>Profils</span><span>Droits</span></div><strong>Administrer les accès →</strong></button>`:'';document.getElementById('portal').innerHTML=`<div class="portal-hero site-home-hero"><div><div class="portal-badge">🏸 TBK - Tennis Badminton Kersaint</div><h1>Bienvenue sur le portail du club</h1><p>Cette page est l'accueil du site internet TBK. Choisissez votre espace : suivi des inscriptions 2026-2027 ou gestion des tournois.</p></div><div class="portal-season">TBK<br><span>Club</span></div></div><div class="portal-grid site-home-grid"><button class="portal-card registration-card" onclick="openInscriptionsHome()"><div class="portal-icon">📝</div><h2>Inscriptions 2026-2027</h2><p>Gestion des adhérents, cotisations, licences UFOLEP, WhatsApp, santé, paiements et informations de contact.</p><div class="portal-mini-kpis"><span>Adhérents</span><span>Cotisations</span><span>Licences</span></div><strong>Accéder aux inscriptions →</strong></button><button class="portal-card tournament-card" onclick="openTournamentHome()"><div class="portal-icon">🏆</div><h2>Gestion Tournoi</h2><p>Accès à la gestion des équipes, poules, classements, planning global, scores, émargement et tableaux finaux.</p><div class="portal-mini-kpis"><span>${done}/${total.length} matchs joués</span><span>${present}/96 présents</span><span>${paid}/96 paiements</span></div><strong>Accéder au tournoi →</strong></button>${adminCard}${documentationCard}</div><div class="card notice site-home-note"><b>Navigation simplifiée :</b> les anciens boutons techniques ne sont plus affichés dans le menu principal. Les écrans détaillés restent accessibles depuis l'espace Gestion Tournoi.</div>`}

function renderDocumentation(){let el=document.getElementById('documentation');if(!el)return;if(!canAccessTab('documentation')){el.innerHTML=`<div class="card notice"><h2>Accès non autorisé</h2><p>La documentation est accessible uniquement si le droit Documentation est coché pour ton profil.</p></div>`;return}el.innerHTML=`<div class="card module-nav"><button onclick="backHome()">← Retour à l'accueil</button><button onclick="switchTab('adminUsers')">🔐 Administration</button></div><div class="card wide documentation-page"><h2>📚 Documentation utilisateur détaillée - Site TBK</h2><p class="small">Cette documentation décrit les fonctionnalités disponibles et les règles de gestion intégrées dans la version en cours du site TBK.</p><div class="toc"><a href="#doc-acces">Accès</a><a href="#doc-accueil">Accueil</a><a href="#doc-inscriptions">Inscriptions</a><a href="#doc-colonnes">Colonnes</a><a href="#doc-tournoi">Tournoi</a><a href="#doc-scores">Scores</a><a href="#doc-emargement">Émargement</a><a href="#doc-donnees">Données</a></div><div class="doc-block doc-warning"><b>Règle de sécurité principale :</b> cette section est visible uniquement pour les profils ayant le droit Documentation. Les boutons du bandeau supérieur ne s'affichent que s'ils sont explicitement cochés dans les droits du profil connecté.</div><h3 id="doc-acces">1. Connexion, profils et droits</h3><div class="doc-grid"><div class="doc-card"><h4>Authentification</h4><ul><li>L'accès au site passe par une page de connexion.</li><li>Un utilisateur doit saisir un identifiant et un mot de passe valides.</li><li>Un utilisateur désactivé ne peut pas se connecter.</li><li>La session est conservée dans l'onglet du navigateur via <code>sessionStorage</code>.</li></ul></div><div class="doc-card"><h4>Profils système</h4><ul><li><b>Administrateur</b> : accès complet par défaut, gestion des utilisateurs, droits et documentation.</li><li><b>Bureau</b> : accès club et tournoi selon droits paramétrés.</li><li><b>Tournoi</b> : accès centré sur la gestion tournoi.</li></ul></div><div class="doc-card"><h4>Droits par profil</h4><ul><li>Chaque profil possède une liste de pages autorisées.</li><li>Chaque profil possède une liste de boutons visibles dans le bandeau supérieur.</li><li>Un bouton non coché pour le profil connecté reste masqué, y compris après rafraîchissement F5.</li><li>La documentation est paramétrable depuis les droits de pages du profil.</li></ul></div></div><h3 id="doc-accueil">2. Onglet Accueil</h3><ul><li>L'accueil affiche le badge <b>TBK - Tennis Badminton Kersaint</b>.</li><li>Il donne accès à l'espace <b>Inscriptions 2026-2027</b> et à l'espace <b>Gestion Tournoi</b>.</li><li>La carte <b>Documentation</b> est affichée uniquement pour les profils ayant le droit Documentation. La carte <b>Administration utilisateurs</b> reste réservée à l'administrateur.</li><li>Les compteurs de l'accueil indiquent notamment le nombre de matchs joués, de présents et de paiements suivis côté tournoi.</li></ul><h3 id="doc-inscriptions">3. Suivi des inscriptions</h3><div class="doc-block"><h4>Objectif</h4><p>L'onglet inscriptions permet de suivre les adhérents, leurs coordonnées, les options sportives, la santé, les cotisations, les paiements et les licences.</p></div><h4>Règles de gestion des inscriptions</h4><ul><li>Chaque ligne représente une inscription ou un adhérent.</li><li>Les données restent modifiables. Lorsqu'une ligne est payée, l'administrateur conserve la capacité de modification.</li><li>La catégorie peut distinguer les adultes et les jeunes.</li><li>Le sport peut distinguer Bad, Ping ou Bad et Ping.</li><li>Le statut UFOLEP permet d'appliquer un supplément si le paramétrage le prévoit.</li><li>Le statut membre du bureau peut appliquer une réduction selon le montant configuré.</li><li>Le statut cotisation payée alimente les indicateurs encaissés et reste à percevoir.</li><li>Les dates sont affichées dans un format lisible pour le suivi opérationnel.</li></ul><h4>Règles de calcul des cotisations</h4><ul><li>La cotisation théorique dépend des paramètres de cotisation adulte, cotisation jeune, supplément Bad + Ping, supplément UFOLEP et réduction bureau.</li><li>Le montant calculé est proposé automatiquement.</li><li>Le montant peut être surchargé manuellement dans la ligne de l'adhérent.</li><li>Le bouton de retour arrière permet de revenir au montant calculé.</li><li>Les KPI affichent le total théorique, le montant encaissé et le reste à percevoir.</li></ul><h3 id="doc-colonnes">4. Administration des colonnes d'inscription</h3><ul><li>Le panneau d'administration des colonnes est visible uniquement pour l'administrateur.</li><li>L'administrateur peut renommer, masquer, déplacer, ajouter ou supprimer des colonnes personnalisées.</li><li>Les colonnes système peuvent être masquées mais ne sont pas supprimées.</li><li>Les colonnes personnalisées peuvent être de type texte, oui/non, select, date ou nombre.</li><li>Pour une colonne de type <b>select</b>, l'administrateur peut saisir les valeurs possibles, séparées par des virgules.</li><li>Si une seule valeur est renseignée pour un champ select, cette valeur est proposée automatiquement par défaut dans la cellule.</li><li>Les valeurs des colonnes personnalisées sont stockées dans chaque inscription.</li></ul><h3 id="doc-tournoi">5. Gestion Tournoi</h3><h4>Modules disponibles</h4><ul><li>Tableau de bord tournoi.</li><li>Double Mixte.</li><li>Double Homme.</li><li>Planning global.</li><li>Émargement.</li><li>Gestion des équipes, poules, classements et phases finales.</li></ul><h4>Règles générales tournoi</h4><ul><li>Les matchs sont rattachés à une compétition, par exemple DM ou DH.</li><li>Les matchs peuvent être affectés à un terrain disponible.</li><li>Le planning consolide les matchs et leur avancement.</li><li>Les tableaux et classements se mettent à jour après saisie des scores.</li><li>Les équipes absentes ou non disponibles ne doivent pas être affectées à un match en contradiction avec leur statut.</li></ul><h3 id="doc-scores">6. Saisie et validation des scores</h3><ul><li>Les scores sont saisis set par set.</li><li>La saisie est stabilisée : la valeur est prise en compte au changement de champ ou validation du champ, pas à chaque frappe.</li><li>La tabulation permet de passer au score suivant.</li><li>Un match est considéré terminé lorsque les scores permettent d'identifier un vainqueur.</li><li>Une fois le match terminé, la zone terrain mentionne le terrain avec le suffixe <b>- Terminé</b>.</li><li>Si un score d'un match terminé est modifié, une confirmation est demandée.</li><li>Si la modification est annulée, le score précédent est conservé.</li><li>Un match terminé libère le terrain pour les autres affectations.</li></ul><h3 id="doc-emargement">7. Émargement, présence et paiement tournoi</h3><ul><li>L'émargement permet de suivre la présence des participants ou équipes.</li><li>Le statut absent bloque les opérations qui seraient incohérentes avec la présence requise.</li><li>Le paiement ou la cotisation tournoi peut être suivi par participant ou équipe selon les données chargées.</li><li>Les compteurs de présence et paiement alimentent l'accueil tournoi et les indicateurs.</li></ul><h3 id="doc-donnees">8. Sauvegarde, import, export et réinitialisation</h3><div class="doc-grid"><div class="doc-card"><h4>Sauvegarder</h4><ul><li>Les données sont enregistrées localement dans le navigateur.</li><li>Le bouton n'apparaît que si le profil y est autorisé.</li></ul></div><div class="doc-card"><h4>Export JSON</h4><ul><li>Permet d'exporter les données pour sauvegarde externe ou transfert.</li><li>Visible uniquement si le profil connecté possède le droit correspondant.</li></ul></div><div class="doc-card"><h4>Import JSON</h4><ul><li>Permet de réimporter un fichier de données.</li><li>À réserver aux utilisateurs habilités, car l'import peut remplacer l'état courant.</li></ul></div><div class="doc-card"><h4>Effacer scores</h4><ul><li>Réinitialise les scores selon l'action prévue dans le site.</li><li>Doit rester limité aux profils autorisés.</li></ul></div><div class="doc-card"><h4>Réinitialiser tout</h4><ul><li>Réinitialise l'ensemble des données locales.</li><li>Action sensible, réservée aux profils explicitement autorisés.</li></ul></div></div><h3>9. Règles d'exploitation recommandées</h3><ul><li>Avant un tournoi ou un forum, effectuer un export JSON de sauvegarde.</li><li>Limiter les boutons sensibles aux profils administrateur ou bureau.</li><li>Vérifier les droits des nouveaux profils avant de les utiliser en réel.</li><li>Après modification de colonnes select, contrôler une inscription test pour confirmer les valeurs proposées.</li><li>En cas de doute sur les données locales, exporter avant toute réinitialisation.</li></ul></div>`}

function renderUserAdmin(){let el=document.getElementById('adminUsers');if(!el)return;if(!isAdminUser()){el.innerHTML=`<div class="card notice"><h2>Accès réservé administrateur</h2><p>Cette page est uniquement accessible au profil administrateur.</p></div>`;return}let users=getAuthUsers(),profiles=getAuthProfiles();let profileOpts=Object.entries(profiles).map(([id,p])=>`<option value="${esc(id)}">${esc(p.label||id)}</option>`).join('');let userRows=users.map((u,i)=>`<tr><td><b>${esc(u.login)}</b></td><td><input value="${esc(u.label||'')}" onchange="updateAdminUser(${i},'label',this.value)"></td><td><select onchange="updateAdminUser(${i},'role',this.value)">${Object.entries(profiles).map(([id,p])=>`<option value="${esc(id)}" ${u.role===id?'selected':''}>${esc(p.label||id)}</option>`).join('')}</select></td><td><input type="checkbox" ${u.active!==false?'checked':''} onchange="updateAdminUser(${i},'active',this.checked)"></td><td><div class="reset-pass"><input id="reset_${i}" type="text" placeholder="Nouveau mot de passe"><button class="secondary" onclick="resetAdminPassword(${i})">Réinitialiser</button></div></td><td>${u.login==='admin'?'<span class="small">Protégé</span>':`<button class="danger" onclick="deleteAdminUser(${i})">Supprimer</button>`}</td></tr>`).join('');let profileRows=Object.entries(profiles).map(([id,p])=>{p.toolbarButtons=Array.isArray(p.toolbarButtons)?p.toolbarButtons:defaultToolbarRights(id);return `<div class="profile-card"><div class="profile-title"><input value="${esc(p.label||id)}" onchange="renameAdminProfile('${esc(id)}',this.value)"><span class="profile-id">${esc(id)}</span></div><h4 class="rights-title">Pages du site</h4><div class="rights-grid">${TBK_PAGES.map(page=>`<label><input type="checkbox" ${((p.pages||[]).includes(page.id))?'checked':''} onchange="toggleProfileRight('${esc(id)}','${page.id}',this.checked)"> ${esc(page.label)}</label>`).join('')}</div><h4 class="rights-title toolbar-rights-title">Boutons partie haute</h4><div class="rights-grid toolbar-rights-grid">${TBK_TOOLBAR_BUTTONS.map(btn=>`<label><input type="checkbox" ${(p.toolbarButtons||[]).includes(btn.id)?'checked':''} onchange="toggleProfileToolbarRight('${esc(id)}','${btn.id}',this.checked)"> ${esc(btn.label)}</label>`).join('')}</div>${['administrateur','bureau','tournoi'].includes(id)?'<div class="small">Profil système</div>':`<button class="danger" onclick="deleteAdminProfile('${esc(id)}')">Supprimer le profil</button>`}</div>`}).join('');el.innerHTML=`<div class="card module-nav"><button onclick="backHome()">← Retour à l'accueil</button></div><div class="card"><h2>Administration des utilisateurs et droits</h2><p class="small">Espace réservé au profil administrateur. Tu peux gérer les utilisateurs, les accès aux pages et maintenant la présence des boutons de la partie haute par profil.</p></div><div class="admin-grid"><div class="card"><h3>Ajouter un utilisateur</h3><div class="admin-form"><label>Identifiant<input id="newUserLogin" placeholder="ex : benevole1"></label><label>Nom affiché<input id="newUserLabel" placeholder="ex : Bénévole tournoi"></label><label>Mot de passe<input id="newUserPassword" placeholder="Mot de passe initial"></label><label>Profil<select id="newUserRole">${profileOpts}</select></label><button onclick="addAdminUser()">➕ Ajouter l'utilisateur</button><div id="adminUserMsg" class="small"></div></div></div><div class="card"><h3>Créer un profil</h3><div class="admin-form"><label>Code profil<input id="newProfileId" placeholder="ex : communication"></label><label>Libellé<input id="newProfileLabel" placeholder="ex : Communication"></label><button onclick="addAdminProfile()">➕ Ajouter le profil</button><div class="small">Après création, coche les pages et les boutons autorisés ci-dessous.</div></div></div></div><div class="card wide"><h3>Utilisateurs</h3><table class="excel admin-users-table"><tr><th>Identifiant</th><th>Nom affiché</th><th>Profil</th><th>Actif</th><th>Réinitialiser mot de passe</th><th>Action</th></tr>${userRows}</table></div><div class="card wide"><h3>Droits par profil</h3><div class="small" style="margin-bottom:10px">Chaque profil peut avoir ses propres droits sur les pages du site et sur les boutons du bandeau supérieur.</div><div class="profiles-grid">${profileRows}</div></div>`}
function addAdminUser(){let login=(document.getElementById('newUserLogin')?.value||'').trim().toLowerCase(),label=(document.getElementById('newUserLabel')?.value||'').trim(),password=document.getElementById('newUserPassword')?.value||'',role=document.getElementById('newUserRole')?.value||'tournoi',msg=document.getElementById('adminUserMsg');let users=getAuthUsers();if(!login||!password){if(msg)msg.textContent='Identifiant et mot de passe obligatoires.';return}if(users.some(u=>String(u.login).toLowerCase()===login)){if(msg)msg.textContent='Cet identifiant existe déjà.';return}users.push({login,label:label||login,password,role,active:true});saveAuthUsers(users);renderUserAdmin()}
function updateAdminUser(i,field,value){let users=getAuthUsers();if(!users[i])return;users[i][field]=value;saveAuthUsers(users);updateAuthChrome();renderUserAdmin()}
function resetAdminPassword(i){let input=document.getElementById('reset_'+i),password=input?.value||'';if(!password){alert('Saisis un nouveau mot de passe.');return}let users=getAuthUsers();if(!users[i])return;users[i].password=password;saveAuthUsers(users);alert('Mot de passe réinitialisé.');renderUserAdmin()}
function deleteAdminUser(i){let users=getAuthUsers();if(!users[i]||users[i].login==='admin')return;if(!confirm('Supprimer cet utilisateur ?'))return;users.splice(i,1);saveAuthUsers(users);renderUserAdmin()}
function addAdminProfile(){let id=(document.getElementById('newProfileId')?.value||'').trim().toLowerCase().replace(/[^a-z0-9_-]/g,''),label=(document.getElementById('newProfileLabel')?.value||'').trim(),profiles=getAuthProfiles();if(!id||profiles[id]){alert('Code profil invalide ou déjà existant.');return}profiles[id]={label:label||id,pages:[],toolbarButtons:defaultToolbarRights(id)};saveAuthProfiles(profiles);renderUserAdmin()}
function renameAdminProfile(id,label){let profiles=getAuthProfiles();if(!profiles[id])return;profiles[id].label=label||id;saveAuthProfiles(profiles);updateAuthChrome();renderUserAdmin()}
function toggleProfileRight(id,page,checked){let profiles=getAuthProfiles();if(!profiles[id])return;profiles[id].pages=profiles[id].pages||[];if(checked&&!profiles[id].pages.includes(page))profiles[id].pages.push(page);if(!checked)profiles[id].pages=profiles[id].pages.filter(x=>x!==page);saveAuthProfiles(profiles);updateAuthChrome()}

function toggleProfileToolbarRight(id,button,checked){let profiles=getAuthProfiles();if(!profiles[id])return;profiles[id].toolbarButtons=profiles[id].toolbarButtons||[];if(checked&&!profiles[id].toolbarButtons.includes(button))profiles[id].toolbarButtons.push(button);if(!checked)profiles[id].toolbarButtons=profiles[id].toolbarButtons.filter(x=>x!==button);saveAuthProfiles(profiles);updateToolbarRights();renderUserAdmin()}
function deleteAdminProfile(id){let profiles=getAuthProfiles();if(['administrateur','bureau','tournoi'].includes(id))return;if(!confirm('Supprimer ce profil ? Les utilisateurs associés devront être réaffectés.'))return;delete profiles[id];saveAuthProfiles(profiles);let users=getAuthUsers().map(u=>u.role===id?{...u,role:'tournoi'}:u);saveAuthUsers(users);renderUserAdmin()}

if(!currentUser()){document.body.classList.remove('is-authenticated');document.querySelectorAll('[data-toolbar]').forEach(el=>{el.hidden=true;el.style.display='none'});}
forceHideToolbarButtons();
renderAll(true);
renderLogin();
updateAuthChrome();
enforceCurrentAccess();
updateAuthChrome();
window.addEventListener('pageshow',()=>{forceHideToolbarButtons();updateAuthChrome();updateToolbarRights();});
window.addEventListener('focus',()=>{updateAuthChrome();updateToolbarRights();});
applySavedColumnWidths();
updateAdminToolbar();
